const labels={UPLOADED:'업로드 완료',PREPROCESSING:'전처리 중',PREPROCESSED:'전처리 완료',MAPPING:'매핑 중',VALIDATING:'판정 대기·진행',COMPLETED:'처리 완료',REVIEW_REQUIRED:'검토 필요',FAILED:'처리 실패',MET:'충족',NOT_MET:'미충족',UNKNOWN:'판단 불가',PRIMARY:'주요 관련',RELATED:'참고 관련',PENDING:'검토 대기',APPROVED:'승인',MODIFIED:'수정',REJECTED:'반려',NOT_REQUIRED:'검토 불필요'};
