let config;try{config=JSON.parse(localStorage.getItem('isms.settings'))||{}}catch{config={}}const standalone=location.port==='8080',backendUrl=!/^https?:$/.test(location.protocol)?'':standalone?'http://127.0.0.1:8000':location.origin;config={mode:backendUrl&&!standalone?'live':'demo',integration:backendUrl,input:backendUrl,...config};
const state={view:'home',tab:'mapping',selected:null,query:'',filter:'',page:1,files:[],busy:false,phase:'upload',data:[],liveResult:null,user:null,accounts:[],companies:[],invites:[],verifyTokens:{},authCtx:null,team:null,audit:[],platform:null,platformAudit:[],ops:null,opsLoading:false,pendingEmail:''};
function sample(id,name,control,status,outcome,source='text',provisional=false){const quote=control==='2.5.1'?'사용자 계정은 담당 부서의 승인 후 생성하며, 분기별로 계정 및 접근권한의 적정성을 검토한다.':control==='2.9.4'?'정보시스템의 접속기록을 수집하며, 담당자는 매월 기록을 점검하고 결과를 보관한다.':'외부 네트워크 접근은 방화벽 정책에 따라 제한하며, 허용된 사용자에 대해서만 접속을 허용한다.';const items=[{item_id:control+'-Q01',question:'관리 절차를 정의하고 있는가?',result:'MET',reason:'문서에 관리 절차와 담당자가 명시되어 있다.',check_kind:'procedure',critical:true,citations:[{chunk_id:id+'_C001',page:3,quote,source}]},{item_id:control+'-Q02',question:'정의한 절차를 실제로 이행하고 있는가?',result:outcome==='미충족'?'NOT_MET':outcome==='충족'?'MET':'UNKNOWN',reason:outcome==='미충족'?'제출된 점검 기록에 필수 점검이 수행되지 않은 것으로 기록되어 있다.':outcome==='충족'?'수행 결과와 승인 기록이 함께 확인된다.':'절차 문서만으로 실제 이행 여부를 확인하기 어렵다.',check_kind:'implementation',critical:true,reason_codes:outcome==='미충족'?['P2_NM_REQUIRED_ACTION_NOT_DONE']:outcome==='충족'?[]:['P2_U_EVIDENCE_INSUFFICIENT'],citations:outcome==='충족'||outcome==='미충족'?[{chunk_id:id+'_C002',page:5,quote:outcome==='미충족'?'이번 분기 정기 점검은 미실시로 기록하였다.':'2026년 3분기 정기 점검을 수행하고 담당자 승인을 완료하였다.',source}]:[]},{item_id:control+'-Q03',question:'수행 기록을 보관하고 있는가?',result:outcome==='충족'?'MET':'UNKNOWN',reason:outcome==='충족'?'점검 기록과 담당자 승인 내역이 보관되어 있다.':'추가 수행 기록 제출이 필요하다.',check_kind:'record',critical:false,reason_codes:outcome==='충족'?[]:['P2_U_EVIDENCE_INSUFFICIENT'],citations:outcome==='충족'?[{chunk_id:id+'_C002',page:5,quote:'2026년 3분기 정기 점검을 수행하고 담당자 승인을 완료하였다.',source}]:[]}];return {evidence_id:id,name,version:1,uploaded_at:'2026-10-05 09:30',size:245760,status,control_id:control,control_name:catalog.find(c=>c[0]===control)?.[1],relation:'PRIMARY',quote,source,items,outcome,provisional,review:status==='REVIEW_REQUIRED',review_status:status==='REVIEW_REQUIRED'?'PENDING':'NOT_REQUIRED',review_reasons:source==='ocr'?['P2R203']:outcome==='미충족'?['P2R201']:['P2R111'],history:[],versions:[1],similarity:.83,confidence:.91,validation:true};}
const demo=[sample('E0001','사용자 계정 관리 절차서.pdf','2.5.1','COMPLETED','충족'),sample('E0002','3분기 접근권한 점검표.xlsx','2.5.1','REVIEW_REQUIRED','미충족'),sample('E0003','방화벽 정책 운영지침.docx','2.6.1','REVIEW_REQUIRED','확인 필요'),sample('E0004','접속기록 점검 결과.pdf','2.9.4','COMPLETED','충족'),sample('E0005','계정 승인 기록 스캔.png','2.5.1','REVIEW_REQUIRED','확인 필요','ocr',true),{evidence_id:'E0006',name:'교육장 예약 안내.txt',version:1,uploaded_at:'2026-10-05 10:10',size:2048,status:'COMPLETED',review:false,items:[],outcome:'증적 없음',versions:[1],history:[],no_match:true},{evidence_id:'E0007',name:'손상된 점검 기록.pdf',version:1,uploaded_at:'2026-10-05 10:15',size:1024,status:'FAILED',review:false,items:[],versions:[1],history:[],error:'전처리 실패 · 파일을 읽을 수 없습니다.'}];
state.data=config.mode==='demo'?structuredClone(demo):[];
function badge(value){let color=['COMPLETED','MET','충족','APPROVED'].includes(value)?'green':['REVIEW_REQUIRED','UNKNOWN','확인 필요','충족(보완 권고)','PENDING'].includes(value)?'amber':['FAILED','NOT_MET','미충족','REJECTED'].includes(value)?'red':'blue';return `<span class="badge ${color}">${esc(labels[value]||value)}</span>`}
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',4500)}
function go(view){state.view=view;window.scrollTo?.({top:0,behavior:'instant'});state.selected=null;state.query='';state.filter='';state.page=1;render()}
function openDetail(id){state.selected=state.data.find(d=>d.evidence_id===id);state.tab='mapping';render()}
function nav(){return `<aside class="sidebar"><button class="brand brand-home" data-go="home" aria-label="도구 소개로 돌아가기"><img class="brand-logo" src="assets/is-so-logo.png" alt="증적있소 로고"><div><strong>is so</strong><small>증적있소</small></div></button><button class="nav" data-go="home">도구 소개</button>${(isOperator()?opsMenu:[['dashboard','◫','대시보드'],['evidence','▤','증적 관리'],['review','☑','검토 대기'],['controls','▦','통제항목별 결과'],...(state.user&&can('team')?[['team','◎','회사 구성원']]:[])]).map(([v,i,t])=>`${v==='team'?'<hr class="nav-divider">':''}<button class="nav ${state.view===v?'active':''}" data-go="${v}">${t}${v==='review'?` <span class="badge">${state.data.filter(x=>x.review).length}</span>`:''}</button>`).join('')}<div class="side-bottom">${state.user?`<p class="side-user"><strong>${esc(state.user.name)}</strong> ${roleBadge(state.user.role)}<br>${esc(state.user.email)}</p><button class="btn" id="logout">로그아웃</button>`:`<p>증적 등록 · 관련성 매핑<br>문항 판정 · 검토 기록</p><button class="btn" data-go="login">로그인</button>`}<button class="btn" id="settings">연결 설정</button></div></aside>`}
function render(){window.cleanupReadingFlow?.();if(authViews.includes(state.view)){state.selected=null;$('#app').innerHTML=authPage();bind();($('#authForm input:not([value]):not([readonly]),#authForm input[value=""]')||$('.auth-card .auth-submit'))?.focus();return}if(state.view==='home'){state.selected=null;$('#app').innerHTML=home();bind();window.setupReadingFlow?.();return}const opsView=state.view.startsWith('ops-');if(opsView!==isOperator()){state.view=opsView?'home':'ops-companies';return render()}const title=opsView?opsInfo[state.view][0]:{dashboard:'대시보드',evidence:'증적 관리',controls:'통제항목별 결과',review:'검토 대기',team:'회사 구성원'}[state.view];$('#app').innerHTML=`<div class="layout">${nav()}<main><div class="topline"><span>${opsView?'운영 관리':'작업 공간'} / ${title}</span><span class="mode">${config.mode==='demo'?'데모 모드 · 예시 데이터':'서버 연결 모드'}</span></div>${state.selected?detail():`<div class="heading"><div><h1>${title}</h1><p class="muted">${opsView?opsInfo[state.view][1]:{dashboard:'등록된 증적의 처리 상태와 검토 필요 현황입니다.',evidence:'정책서·절차서·점검표·이행 기록을 등록하고, 파일별 결과를 확인합니다.',controls:'연결된 증적과 문항별 판단 근거를 통제항목 기준으로 조회합니다.',review:'자동 판정만으로 확정하기 어려운 결과와 검토 사유를 확인합니다.',team:'같은 회사 도메인의 직원을 초대하고 가입 상태를 확인합니다.'}[state.view]}</p></div>${opsView||['evidence','team'].includes(state.view)?'':'<button class="btn primary" data-start-upload>증적 업로드</button>'}</div>${opsView?opsPage():state.view==='dashboard'?dashboard():state.view==='evidence'?evidence():state.view==='controls'?controls():state.view==='team'?team():review()}` }<div class="foot"><span>증적있소 · is so</span><span>${config.mode==='demo'?'예시 판정 · 새로고침 시 데모 변경 초기화':'판정은 연결된 서버의 결과를 사용합니다'}</span></div></main></div>`;bind();}


// Accounts: one admin per company domain verifies by email link, then invites staff from the same domain.
// Demo mode keeps companies, accounts and links in page memory; live mode expects the /api/auth/*, /api/company/*, /api/invites/* routes below.
const authViews=['login','signup','verify','invite'],freeMail=['gmail.com','naver.com','daum.net','hanmail.net','kakao.com','nate.com','hotmail.com','outlook.com','live.com','yahoo.com','icloud.com'];
const domainOf=e=>String(e).split('@')[1]||'',newToken=()=>globalThis.crypto?.randomUUID?.()||Math.random().toString(36).slice(2)+Date.now().toString(36),validEmail=e=>/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(e),passwordError=(pw,pw2)=>!(pw.length>=8&&/[A-Za-z]/.test(pw)&&/\d/.test(pw))?'비밀번호는 영문과 숫자를 포함해 8자 이상이어야 합니다.':pw!==pw2?'비밀번호가 서로 일치하지 않습니다.':'';
function authButtons(){return state.user?`<span class="user-chip" title="${esc(state.user.email)}">${esc(state.user.company?state.user.company+' · ':'')}${esc(state.user.name)}님</span><button class="header-link" id="logout">로그아웃</button><button class="btn primary" data-go="dashboard">작업 공간으로</button>`:`<button class="header-link" data-go="login">로그인</button><button class="btn primary" data-go="signup">회사 가입</button>`}
function siteHeader(){return `<header class="project-header"><button class="project-brand" data-go="home"><span class="brand-mark"><img src="assets/is-so-logo.png" alt="증적있소 로고"></span><span class="brand-caption"><b class="brand-name">is so <span>증적 있소</span></b><span class="brand-description">ISMS-P 증적 검토 도구<small>증적과 기준을 명확하게.</small></span></span></button><div class="header-actions">${authButtons()}<button class="btn" id="settings">연결 설정</button></div></header>`}
function authField(label,name,type,auto,extra=''){return `<label class="field">${label}<input name="${name}" type="${type}" autocomplete="${auto}" ${extra}></label>`}
const pwFields=()=>authField('비밀번호','password','password','new-password','required')+'<p class="field-hint">영문과 숫자를 포함해 8자 이상</p>'+authField('비밀번호 확인','password2','password','new-password','required');
const demoNote=s=>config.mode==='demo'?`<div class="notice demo-mail"><strong>데모 모드</strong> · ${s}</div>`:'';
function authBody(){const a=state.authCtx||{};switch(state.view){
case 'signup':return `<h1 id="auth-title">회사 가입</h1><p class="muted">회사 대표(관리자) 계정을 만듭니다. 직원은 가입 후 관리자가 초대합니다.</p><form id="authForm" novalidate>${authField('회사명','company','text','organization','required')}${authField('관리자 이름','name','text','name','required')}${authField('회사 이메일','email','email','username','required')}<p class="field-hint">회사 도메인 메일만 가입할 수 있으며, 한 회사(도메인)는 한 번만 등록됩니다.</p>${pwFields()}<p class="auth-error" id="authError" role="alert" hidden></p><button class="btn primary auth-submit" type="submit">인증 메일 받기</button></form><p class="auth-switch">이미 계정이 있으신가요? <button class="link" data-go="login">로그인</button></p><p class="auth-switch">직원이신가요? 회사 관리자에게 초대를 요청하세요.</p>`;
case 'verify':return a.status==='done'?`<div class="auth-state ok" aria-hidden="true">✓</div><h1 id="auth-title">이메일 인증 완료</h1><p class="muted">${esc(a.email)} 계정 인증이 끝났습니다. ${a.pendingApproval?'운영자가 회사 가입을 승인하면 로그인할 수 있으며, 승인 결과는 메일로 알려드립니다.':'이제 로그인할 수 있습니다.'}</p><button class="btn primary auth-submit" data-go="login">로그인하기</button>`:a.status==='error'?`<div class="auth-state bad" aria-hidden="true">!</div><h1 id="auth-title">인증 링크를 확인할 수 없습니다</h1><p class="muted">${esc(a.message||'링크가 만료되었거나 이미 사용되었습니다.')} 로그인 화면에서 인증 메일을 다시 받을 수 있습니다.</p><button class="btn primary auth-submit" data-go="login">로그인으로</button>`:`<div class="auth-state" aria-hidden="true">✉</div><h1 id="auth-title">이메일을 확인하세요</h1><p class="muted"><strong>${esc(a.email)}</strong>로 인증 링크를 보냈습니다. 메일의 링크를 눌러 가입을 완료하세요. 링크는 24시간 동안 유효합니다.</p><p class="field-hint">메일이 보이지 않으면 스팸함을 확인하거나 다시 보내기를 누르세요.</p><button class="btn primary auth-submit" id="resendVerify">인증 메일 다시 보내기</button><p class="auth-switch"><button class="link" data-go="login">로그인으로 돌아가기</button></p>${demoNote(`실제 메일은 발송되지 않습니다. 아래 버튼이 메일 속 인증 링크를 대신합니다.<br><button class="btn" data-demo-verify="${esc(a.demoToken||'')}">인증 링크 열기</button>`)}`;
case 'invite':return !a.invite?`<div class="auth-state bad" aria-hidden="true">!</div><h1 id="auth-title">초대 링크를 확인할 수 없습니다</h1><p class="muted">${esc(a.message||'초대가 만료되었거나 취소되었습니다.')} 회사 관리자에게 다시 초대를 요청하세요.</p><button class="btn primary auth-submit" data-go="home">처음으로</button>`:`<h1 id="auth-title">${esc(a.invite.company)} 초대</h1><p class="muted">초대를 수락하고 직원 계정을 만듭니다. 초대 링크로 이메일 인증이 함께 완료됩니다.</p><form id="authForm" novalidate>${authField('회사 이메일','email','email','username',`readonly value="${esc(a.invite.email)}"`)}${authField('이름','name','text','name','required')}${pwFields()}<p class="auth-error" id="authError" role="alert" hidden></p><button class="btn primary auth-submit" type="submit">초대 수락하고 가입</button></form>`;
default:return `<h1 id="auth-title">로그인</h1><p class="muted">증적 사전점검 작업 공간에 로그인합니다.</p><form id="authForm" novalidate>${authField('회사 이메일','email','email','username',`required value="${esc(state.pendingEmail)}"`)}${authField('비밀번호','password','password','current-password','required')}<p class="auth-error" id="authError" role="alert" hidden></p><button class="btn primary auth-submit" type="submit">로그인</button></form><p class="auth-switch">회사가 아직 등록되지 않았나요? <button class="link" data-go="signup">회사 가입</button></p>`}}
function authPage(){return `<div class="auth-screen">${siteHeader()}<div class="auth-main"><section class="auth-card" aria-labelledby="auth-title">${authBody()}${state.view==='login'&&state.companies.some(c=>c.id==='C0')?demoNote(`데모 계정으로 바로 로그인해 역할별 화면을 확인할 수 있습니다.<span class="demo-logins">${state.accounts.filter(a=>a.companyId==='C0').map(a=>`<button class="btn" data-demo-login="${esc(a.email)}">${a.role==='super'?'서비스 운영 관리자':'데모회사 '+roles[a.role].label} · ${esc(a.name)}</button>`).join('')}</span>`):''}${state.view==='signup'||state.view==='login'?demoNote('가입 정보는 이 페이지에만 임시로 보관하며, 새로고침하면 사라집니다.'):''}</section></div></div>`}
function authError(msg,resendEmail){const el=$('#authError');el.innerHTML=esc(msg)+(resendEmail?` <button class="link" id="resendFromLogin">인증 메일 다시 받기</button>`:'');el.hidden=false;if(resendEmail)$('#resendFromLogin').onclick=()=>{state.authCtx={email:resendEmail};resendVerify()}}
async function submitAuth(e){e.preventDefault();const f=e.target,v=n=>f.elements[n]?.value.trim()??'',view=state.view,email=v('email').toLowerCase(),pw=f.elements.password.value,pw2=f.elements.password2?.value;let err='';
if(view==='signup'&&!v('company'))err='회사명을 입력하세요.';else if(view!=='login'&&!v('name'))err='이름을 입력하세요.';else if(!validEmail(email))err='이메일 형식을 확인하세요.';else if(view==='signup'&&state.platform.blockedDomains.includes(domainOf(email)))err=(freeMail.includes(domainOf(email))?'개인 메일(':'가입이 제한된 도메인(')+domainOf(email)+')은 사용할 수 없습니다. 회사 이메일을 입력하세요.';else if(!pw)err='비밀번호를 입력하세요.';else if(view!=='login')err=passwordError(pw,pw2);if(err)return authError(err);
const btn=f.querySelector('[type=submit]');btn.disabled=true;try{if(view==='signup')await signupCompany(v('company'),v('name'),email,pw);else if(view==='invite')await acceptInvite(v('name'),pw);else await login(email,pw)}catch(x){authError(x.message,x.unverified&&email);btn.disabled=false}}
async function signupCompany(company,name,email,password){let demoToken;if(config.mode==='demo'){if(state.companies.some(c=>c.domain===domainOf(email)))throw Error('이미 등록된 회사 도메인입니다. 회사 관리자에게 초대를 요청하세요.');const c={id:'C'+(state.companies.length+1),name:company,domain:domainOf(email),status:state.platform.requireApproval?'pending':'active',createdAt:new Date().toLocaleDateString('ko-KR',{timeZone:'Asia/Seoul'})};state.companies.push(c);state.accounts.push({email,name,password,companyId:c.id,role:'admin',verified:false,active:true});demoToken=newToken();state.verifyTokens[demoToken]=email}else await api(config.integration,'/api/auth/signup',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({company,name,email,password})});state.authCtx={email,status:'sent',demoToken};go('verify')}
async function resendVerify(){const a=state.authCtx||{};try{if(config.mode==='demo'){const acc=state.accounts.find(x=>x.email===a.email);if(!acc||acc.verified)throw Error('인증을 기다리는 계정이 아닙니다.');for(const t in state.verifyTokens)if(state.verifyTokens[t]===a.email)delete state.verifyTokens[t];a.demoToken=newToken();state.verifyTokens[a.demoToken]=a.email}else await api(config.integration,'/api/auth/resend',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:a.email})});state.authCtx={email:a.email,status:'sent',demoToken:a.demoToken};go('verify');toast('인증 메일을 다시 보냈습니다.')}catch(x){toast(x.message)}}
async function verifyEmail(token){try{let email;if(config.mode==='demo'){email=state.verifyTokens[token];const acc=state.accounts.find(x=>x.email===email);if(!acc)throw Error('링크가 만료되었거나 이미 사용되었습니다.');acc.verified=true;delete state.verifyTokens[token];var pendingApproval=state.companies.find(c=>c.id===acc.companyId)?.status==='pending'}else email=(await api(config.integration,'/api/auth/verify',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({token})})).email||'';state.pendingEmail=email;state.authCtx={email,status:'done',pendingApproval}}catch(x){state.authCtx={status:'error',message:x.message}}go('verify')}
async function login(email,password){if(config.mode==='demo'){const acc=state.accounts.find(x=>x.email===email&&x.password===password);if(!acc)throw Error('이메일 또는 비밀번호가 올바르지 않습니다.');if(acc.blocked)throw Error('서비스 운영자가 로그인을 차단한 계정입니다. 서비스 운영자에게 문의하세요.');if(acc.active===false)throw Error('비활성화된 계정입니다. 회사 관리자에게 문의하세요.');const co=state.companies.find(c=>c.id===acc.companyId);if(co&&co.status!=='active'&&acc.verified)throw Error({pending:'운영자가 회사 가입을 확인하고 있습니다. 승인 후 로그인할 수 있습니다.',suspended:'이용이 정지된 회사입니다. 서비스 운영자에게 문의하세요.',rejected:'가입이 거절된 회사입니다. 서비스 운영자에게 문의하세요.'}[co.status]);if(!acc.verified)throw Object.assign(Error('이메일 인증이 완료되지 않았습니다.'),{unverified:true});state.user={name:acc.name,email,role:acc.role,companyId:acc.companyId,company:state.companies.find(c=>c.id===acc.companyId)?.name}}else{const r=await api(config.integration,'/api/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email,password})}).catch(x=>{throw /verif|인증/i.test(x.message)?Object.assign(x,{unverified:true}):x});const u=r.user||r;state.user={name:u.name||email,email,role:u.role||'member',company:u.company||u.company_name,token:r.token||r.access_token}}state.pendingEmail='';state.team=null;state.ops=null;go(state.user.role==='super'?'ops-companies':'dashboard');toast(state.user.name+'님, 환영합니다.')}
function logout(){state.user=null;state.team=null;state.ops=null;if(state.view==='team'||state.view.startsWith('ops-')||authViews.includes(state.view))state.view='home';render();toast('로그아웃했습니다.')}
async function openInvite(token){let invite=null,message='';try{if(config.mode==='demo'){const i=state.invites.find(x=>x.token===token&&x.status==='pending');if(!i)throw Error('초대가 만료되었거나 취소되었습니다.');invite={email:i.email,company:state.companies.find(c=>c.id===i.companyId)?.name}}else invite=await api(config.integration,'/api/invites/'+encodeURIComponent(token))}catch(x){message=x.message}state.authCtx={token,invite,message};go('invite')}
async function acceptInvite(name,password){const a=state.authCtx;if(config.mode==='demo'){const i=state.invites.find(x=>x.token===a.token&&x.status==='pending');if(!i)throw Error('초대가 만료되었거나 취소되었습니다.');i.status='accepted';state.accounts.push({email:i.email,name,password,companyId:i.companyId,role:i.role||'member',verified:true,active:true})}else await api(config.integration,'/api/invites/accept',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({token:a.token,name,password})});state.pendingEmail=a.invite.email;go('login');toast('가입이 완료되었습니다. 로그인하세요.')}
function companyOf(){return state.companies.find(c=>c.id===state.user?.companyId)}
// Roles: the UI hides what a role cannot do; the server must enforce the same rules.
const roles={admin:{label:'관리자',desc:'구성원·권한 관리와 모든 작업'},reviewer:{label:'검토자',desc:'자동 판정의 검토 결정과 증적 작업'},member:{label:'담당자',desc:'증적 등록·점검과 결과 조회'}};
const perms={upload:['admin','reviewer','member'],inspect:['admin','reviewer','member'],review:['admin','reviewer'],delete:['admin'],team:['admin']};
const permLabels=[['upload','증적 업로드·재업로드'],['inspect','점검 실행·결과 조회'],['review','검토 결정 (승인·반려)'],['delete','증적 삭제'],['team','구성원 초대·권한 변경']];
// Signed-out demo visitors keep full access so the demo stays explorable.
function can(action){return state.user?(perms[action]||[]).includes(state.user.role):config.mode==='demo'}
const roleBadge=r=>`<span class="role-badge role-${esc(r)}">${r==='super'?'운영 관리자':roles[r]?.label||esc(r)}</span>`,nowKST=()=>new Date().toLocaleString('ko-KR',{timeZone:'Asia/Seoul'});
function audit(text){state.audit.unshift({at:nowKST(),actor:state.user?.name||'',text})}
function seedDemoCompany(){if(config.mode!=='demo'||state.companies.some(c=>c.id==='C0'))return;state.companies.push({id:'C0',name:'데모회사',domain:'demo.test'});for(const [email,name,role] of [['admin@demo.test','김보안','admin'],['reviewer@demo.test','이검토','reviewer'],['staff@demo.test','박담당','member']])state.accounts.push({email,name,role,password:'demo1234',companyId:'C0',verified:true,active:true})}
function loadTeam(){if(config.mode==='demo'){const c=companyOf();state.team={domain:c?.domain||domainOf(state.user.email),members:state.accounts.filter(a=>a.companyId===c?.id).map(({name,email,role,verified,active})=>({name,email,role,status:active===false?'disabled':verified?'active':'unverified'})),invites:state.invites.filter(i=>i.companyId===c?.id&&i.status==='pending'),audit:state.audit};return}return api(config.integration,'/api/company/members').then(r=>{state.team={domain:r.domain||domainOf(state.user.email),members:r.members||[],invites:r.invites||[],audit:r.audit||[]}}).catch(x=>{state.team={domain:domainOf(state.user.email),members:[],invites:[],audit:[],error:x.message}}).then(render)}
function roleSelect(attrs,value,disabled){return `<select ${attrs} ${disabled?'disabled':''}>${Object.entries(roles).map(([k,r])=>`<option value="${k}" ${k===value?'selected':''}>${r.label}</option>`).join('')}</select>`}
function team(){if(!can('team'))return `<div class="notice">회사 관리자만 구성원과 권한을 관리할 수 있습니다.</div>`;if(config.mode==='demo'||!state.team)loadTeam();const t=state.team;if(!t)return '<div class="card"><p class="muted">구성원 정보를 불러오는 중입니다.</p></div>';const statusLabel={active:['활성','green'],unverified:['인증 대기','amber'],disabled:['비활성','red']};
return `${t.error?`<div class="notice">${esc(t.error)}</div>`:''}<div class="card"><div class="card-head"><div><h2>직원 초대</h2><p class="muted">@${esc(t.domain)} 메일 주소로만 초대할 수 있습니다. 초대 링크는 7일 동안 유효합니다.</p></div></div><form class="invite-form" id="inviteForm" novalidate><input id="inviteEmail" type="email" placeholder="name@${esc(t.domain)}" aria-label="초대할 직원 이메일" autocomplete="off">${roleSelect('id="inviteRole" aria-label="초대할 역할"','member')}<button class="btn primary" type="submit">초대 메일 보내기</button></form></div>
<div class="card"><div class="card-head"><h2>구성원 ${t.members.length}명${t.invites.length?` · 초대 대기 ${t.invites.length}건`:''}</h2></div><div class="table-wrap"><table class="team-table"><thead><tr><th>이름</th><th>이메일</th><th>역할</th><th>상태</th><th><span class="sr-only">관리</span></th></tr></thead><tbody>${t.members.map(m=>{const self=m.email===state.user.email,[sl,sc]=statusLabel[m.status]||[esc(m.status),'blue'];return `<tr><td>${esc(m.name)}${self?' <span class="muted">(나)</span>':''}</td><td>${esc(m.email)}</td><td>${self?roleBadge(m.role):roleSelect(`data-member-role="${esc(m.email)}" aria-label="${esc(m.name)} 역할"`,m.role,m.status==='disabled')}</td><td><span class="badge ${sc}">${sl}</span></td><td class="row-actions">${self?'':`<button class="btn" data-member-toggle="${esc(m.email)}">${m.status==='disabled'?'다시 활성화':'비활성화'}</button><button class="btn danger" data-member-remove="${esc(m.email)}">제거</button>`}</td></tr>`}).join('')}${t.invites.map(i=>`<tr><td class="muted">—</td><td>${esc(i.email)}</td><td>${roleBadge(i.role||'member')}</td><td><span class="badge blue">초대 대기</span></td><td class="row-actions">${config.mode==='demo'?`<button class="btn" data-demo-invite="${esc(i.token)}" title="데모: 초대받은 직원 화면으로 전환합니다">초대 링크 열기</button>`:''}<button class="btn" data-resend-invite="${esc(i.token||i.id)}">다시 보내기</button><button class="btn danger" data-cancel-invite="${esc(i.token||i.id)}">취소</button></td></tr>`).join('')}</tbody></table></div><p class="muted">본인 계정의 역할은 바꿀 수 없어 회사에는 항상 관리자가 한 명 이상 남습니다. 비활성화한 구성원은 로그인할 수 없습니다.${config.mode==='demo'?' 데모 모드에서는 실제 메일을 보내지 않으며, ‘초대 링크 열기’를 누르면 로그아웃되고 초대받은 직원의 가입 화면이 열립니다.':''}</p></div>
<div class="columns team-columns"><div class="card"><div class="card-head"><h2>역할별 권한</h2></div><div class="table-wrap"><table class="perm-table"><thead><tr><th>기능</th>${Object.values(roles).map(r=>`<th>${r.label}</th>`).join('')}</tr></thead><tbody>${permLabels.map(([k,l])=>`<tr><td>${l}</td>${Object.keys(roles).map(r=>perms[k].includes(r)?'<td class="perm-yes" aria-label="가능">●</td>':'<td class="perm-no" aria-label="불가">–</td>').join('')}</tr>`).join('')}</tbody></table></div></div><div class="card"><div class="card-head"><h2>권한 변경 기록</h2><span class="muted">최근 순</span></div>${t.audit?.length?`<ul class="audit-log">${t.audit.slice(0,12).map(a=>`<li><span>${esc(a.text)}</span><small>${esc(a.actor)} · ${esc(a.at)}</small></li>`).join('')}</ul>`:'<div class="empty">아직 기록이 없습니다.</div>'}</div></div>`}
async function sendInvite(e){e.preventDefault();const email=$('#inviteEmail').value.trim().toLowerCase(),role=$('#inviteRole').value,t=state.team;let err=!validEmail(email)?'이메일 형식을 확인하세요.':domainOf(email)!==t.domain?'@'+t.domain+' 메일 주소만 초대할 수 있습니다.':t.members.some(m=>m.email===email)?'이미 가입한 구성원입니다.':t.invites.some(i=>i.email===email)?'이미 초대한 주소입니다. 다시 보내기를 이용하세요.':'';if(err)return toast(err);try{if(config.mode==='demo'){state.invites.push({token:newToken(),email,role,companyId:companyOf().id,status:'pending'});audit(`${email}을 ${roles[role].label}(으)로 초대`)}else{await api(config.integration,'/api/company/invites',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email,role})});state.team=null}render();toast(email+'로 초대 메일을 보냈습니다.')}catch(x){toast(x.message)}}
async function inviteAction(id,action){try{if(config.mode==='demo'){const i=state.invites.find(x=>x.token===id);if(action==='cancel'){i.status='cancelled';audit(`${i.email} 초대 취소`)}else i.token=newToken()}else{await api(config.integration,'/api/company/invites/'+encodeURIComponent(id)+(action==='cancel'?'':'/resend'),{method:action==='cancel'?'DELETE':'POST'});state.team=null}render();toast(action==='cancel'?'초대를 취소했습니다.':'초대 메일을 다시 보냈습니다.')}catch(x){toast(x.message)}}
async function memberAction(email,action,value){const m=state.team.members.find(x=>x.email===email);if(!m||email===state.user.email)return toast('본인 계정은 변경할 수 없습니다.');const text=action==='role'?`${m.name}의 역할을 ${roles[m.role]?.label} → ${roles[value].label}(으)로 변경`:action==='remove'?`${m.name}(${email})을 회사에서 제거`:`${m.name} 계정 ${value?'다시 활성화':'비활성화'}`;try{if(config.mode==='demo'){const i=state.accounts.findIndex(a=>a.email===email);if(action==='role')state.accounts[i].role=value;else if(action==='remove')state.accounts.splice(i,1);else state.accounts[i].active=value;audit(text)}else{await api(config.integration,'/api/company/members/'+encodeURIComponent(email),action==='remove'?{method:'DELETE'}:{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify(action==='role'?{role:value}:{active:value})});state.team=null}render();toast(text+' 완료')}catch(x){toast(x.message);render()}}
function confirmRemove(email){const m=state.team.members.find(x=>x.email===email);showDialog('구성원 제거',`<p><strong>${esc(m.name)}</strong> (${esc(email)})을 회사에서 제거할까요?</p><p class="muted">제거하면 로그인할 수 없으며, 다시 참여하려면 새로 초대해야 합니다. 등록한 증적과 검토 기록은 남습니다.</p><div class="actions"><button class="btn danger" id="confirmRemove">제거</button></div>`);$('#confirmRemove').onclick=()=>{$('#dialog').close();memberAction(email,'remove')}}
function bindTeam(){document.querySelectorAll('[data-member-role]').forEach(s=>s.onchange=()=>memberAction(s.dataset.memberRole,'role',s.value));document.querySelectorAll('[data-member-toggle]').forEach(b=>b.onclick=()=>{const m=state.team.members.find(x=>x.email===b.dataset.memberToggle);memberAction(m.email,'active',m.status==='disabled')});document.querySelectorAll('[data-member-remove]').forEach(b=>b.onclick=()=>confirmRemove(b.dataset.memberRemove));document.querySelectorAll('[data-demo-login]').forEach(b=>b.onclick=()=>{const a=state.accounts.find(x=>x.email===b.dataset.demoLogin);login(a.email,a.password).catch(x=>toast(x.message))})}
// Service operator console: manages companies and accounts across the service, never customer evidence.
// Live mode expects /api/admin/* routes; the server must restrict them to operator accounts.
const opsMenu=[['ops-companies','▦','회사 관리'],['ops-users','◎','사용자 관리'],['ops-log','☰','운영 기록'],['ops-settings','⚙','서비스 설정']];
const opsInfo={'ops-companies':['회사 관리','서비스에 가입한 회사의 승인과 이용 상태를 관리합니다.'],'ops-users':['사용자 관리','모든 회사의 계정 상태를 조회하고 접근을 차단합니다.'],'ops-log':['운영 기록','운영 관리자의 승인·정지·설정 변경 이력입니다.'],'ops-settings':['서비스 설정','가입 정책과 차단 도메인을 설정합니다.']};
const companyStatus={active:['이용 중','green'],pending:['승인 대기','amber'],suspended:['이용 정지','red'],rejected:['가입 거절','red']};
// Demo-only operator login. Anything in this file is visible to every visitor, so real operator accounts must live on the server.
const demoOperator={email:'operator@isms-p.test',password:'demo1234',name:'관리 담당자'};
const isOperator=()=>state.user?.role==='super';
function opsAudit(text){state.platformAudit.unshift({at:nowKST(),actor:state.user?.name||'',text})}
function seedPlatform(){if(config.mode!=='demo'||state.accounts.some(a=>a.role==='super'))return;state.accounts.push({...demoOperator,role:'super',companyId:null,verified:true,active:true});
for(const [id,name,domain,status,createdAt,users] of [['C2','한빛소프트','hanbit.test','active','2026. 9. 18.',[['ceo','최한빛','admin',true],['dev','오개발','member',true],['qa','윤품질','reviewer',false]]],['C3','새솔데이터','saesol.test','pending','2026. 10. 9.',[['admin','한새솔','admin',true]]]]){state.companies.push({id,name,domain,status,createdAt});for(const [u,n,role,verified] of users)state.accounts.push({email:u+'@'+domain,name:n,role,password:'demo1234',companyId:id,verified,active:true})}
for(const c of state.companies){c.status??='active';c.createdAt??='2026. 9. 1.'}}
function opsData(){if(config.mode==='demo')return {companies:state.companies.map(c=>{const us=state.accounts.filter(a=>a.companyId===c.id);return {...c,admin:us.find(a=>a.role==='admin')?.email||'',members:us.length}}),users:state.accounts.filter(a=>a.role!=='super').map(a=>({name:a.name,email:a.email,role:a.role,company:state.companies.find(c=>c.id===a.companyId)?.name||'',status:a.blocked?'blocked':a.active===false?'disabled':a.verified?'active':'unverified'})),audit:state.platformAudit,settings:state.platform};if(!state.ops&&!state.opsLoading){state.opsLoading=true;Promise.all(['/api/admin/companies','/api/admin/users','/api/admin/audit','/api/admin/settings'].map(p=>api(config.integration,p))).then(([c,u,a,s])=>{state.ops={companies:c.items||c,users:u.items||u,audit:a.items||a,settings:s}}).catch(x=>{state.ops={companies:[],users:[],audit:[],settings:state.platform,error:x.message}}).finally(()=>{state.opsLoading=false;render()})}return state.ops}
function opsPage(){const o=opsData();if(!o)return '<div class="card"><p class="muted">운영 정보를 불러오는 중입니다.</p></div>';const err=o.error?`<div class="notice">${esc(o.error)}</div>`:'';const q=state.query.toLowerCase(),match=(...xs)=>!q||xs.join(' ').toLowerCase().includes(q),search=ph=>`<div class="toolbar"><input class="search" id="search" value="${esc(state.query)}" placeholder="${ph}" aria-label="검색">${state.view==='ops-companies'?`<select id="filter" aria-label="상태 필터"><option value="">모든 상태</option>${Object.entries(companyStatus).map(([k,[l]])=>`<option value="${k}" ${state.filter===k?'selected':''}>${l}</option>`).join('')}</select>`:''}</div>`;
if(state.view==='ops-companies'){const cs=o.companies.filter(c=>match(c.name,c.domain,c.admin)&&(!state.filter||c.status===state.filter));return `${err}<div class="metrics">${[['가입 회사',o.companies.length,'전체 등록 회사'],['이용 중',o.companies.filter(c=>c.status==='active').length,'정상 이용 회사'],['승인 대기',o.companies.filter(c=>c.status==='pending').length,'운영자 확인 필요'],['전체 사용자',o.users.length,'회사 구성원 합계']].map(([l,v,s])=>`<div class="metric"><label>${l}</label><strong>${v}</strong><small>${s}</small></div>`).join('')}</div><div class="card"><div class="card-head"><h2>회사 ${cs.length}곳</h2><span class="muted">운영 관리자는 회사의 증적 내용을 열람할 수 없습니다</span></div>${search('회사명, 도메인, 관리자 이메일 검색')}<div class="table-wrap"><table class="team-table"><thead><tr><th>회사</th><th>도메인</th><th>관리자</th><th>구성원</th><th>가입일</th><th>상태</th><th><span class="sr-only">관리</span></th></tr></thead><tbody>${cs.map(c=>{const [l,col]=companyStatus[c.status]||[c.status,'blue'];return `<tr><td><strong>${esc(c.name)}</strong></td><td>@${esc(c.domain)}</td><td>${esc(c.admin)}</td><td><button class="link" data-ops-members="${esc(c.name)}">${c.members}명</button></td><td>${esc(c.createdAt)}</td><td><span class="badge ${col}">${l}</span></td><td class="row-actions">${c.status==='pending'?`<button class="btn green" data-ops-company="${esc(c.id)}" data-status="active">승인</button><button class="btn danger" data-ops-company="${esc(c.id)}" data-status="rejected">거절</button>`:c.status==='active'?`<button class="btn danger" data-ops-company="${esc(c.id)}" data-status="suspended">이용 정지</button>`:c.status==='suspended'?`<button class="btn" data-ops-company="${esc(c.id)}" data-status="active">정지 해제</button>`:''}</td></tr>`}).join('')||'<tr><td colspan="7" class="empty">조건에 맞는 회사가 없습니다.</td></tr>'}</tbody></table></div></div>`}
if(state.view==='ops-users'){const us=o.users.filter(u=>match(u.name,u.email,u.company));const st={active:['활성','green'],unverified:['인증 대기','amber'],disabled:['회사에서 비활성','red'],blocked:['운영자 차단','red']};return `${err}<div class="card"><div class="card-head"><h2>사용자 ${us.length}명</h2><span class="muted">회사 내 역할 변경은 각 회사 관리자가 합니다</span></div>${search('이름, 이메일, 회사 검색')}<div class="table-wrap"><table class="team-table"><thead><tr><th>이름</th><th>이메일</th><th>회사</th><th>역할</th><th>상태</th><th><span class="sr-only">관리</span></th></tr></thead><tbody>${us.map(u=>{const [l,col]=st[u.status]||[u.status,'blue'];return `<tr><td>${esc(u.name)}</td><td>${esc(u.email)}</td><td>${esc(u.company)}</td><td>${roleBadge(u.role)}</td><td><span class="badge ${col}">${l}</span></td><td class="row-actions">${u.status==='unverified'?`<button class="btn" data-ops-resend="${esc(u.email)}">인증 메일 재발송</button>`:''}<button class="btn ${u.status==='blocked'?'':'danger'}" data-ops-user="${esc(u.email)}" data-blocked="${u.status!=='blocked'}">${u.status==='blocked'?'차단 해제':'로그인 차단'}</button></td></tr>`}).join('')||'<tr><td colspan="6" class="empty">조건에 맞는 사용자가 없습니다.</td></tr>'}</tbody></table></div></div>`}
if(state.view==='ops-log')return `${err}<div class="card"><div class="card-head"><h2>운영 기록</h2><span class="muted">최근 순</span></div>${o.audit.length?`<ul class="audit-log">${o.audit.map(a=>`<li><span>${esc(a.text)}</span><small>${esc(a.actor)} · ${esc(a.at)}</small></li>`).join('')}</ul>`:'<div class="empty">아직 기록이 없습니다.</div>'}</div>`;
const s=o.settings;return `${err}<div class="card"><div class="card-head"><div><h2>가입 정책</h2><p class="muted">변경 내용은 이후 가입부터 적용됩니다.</p></div></div><label class="check-row"><input type="checkbox" id="requireApproval" ${s.requireApproval?'checked':''}><span><strong>신규 회사 가입 시 운영자 승인 필요</strong><small>켜면 이메일 인증을 마친 회사도 운영자가 승인해야 로그인할 수 있습니다.</small></span></label><label class="field">가입 차단 도메인<textarea id="blockedDomains" rows="4" aria-describedby="blockedHelp">${esc(s.blockedDomains.join('\n'))}</textarea></label><p class="field-hint" id="blockedHelp">한 줄에 하나씩 입력합니다. 이 도메인의 메일로는 회사 가입을 할 수 없습니다.</p><div class="actions" style="margin-top:16px"><button class="btn primary" id="saveOpsSettings">설정 저장</button></div></div>`}
async function opsUpdate(kind,id,body,text){try{if(config.mode==='demo'){if(kind==='company'){const c=state.companies.find(x=>x.id===id);c.status=body.status}else if(kind==='user'){state.accounts.find(a=>a.email===id).blocked=body.blocked}else Object.assign(state.platform,body);opsAudit(text)}else{await api(config.integration,kind==='settings'?'/api/admin/settings':`/api/admin/${kind==='company'?'companies':'users'}/${encodeURIComponent(id)}`,{method:kind==='settings'?'PUT':'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});state.ops=null}render();toast(text+' 완료')}catch(x){toast(x.message)}}
function opsCompanyAction(id,status){const c=opsData().companies.find(x=>x.id===id),verb={active:c.status==='pending'?'가입 승인':'이용 정지 해제',rejected:'가입 거절',suspended:'이용 정지'}[status];if(status==='active')return opsUpdate('company',id,{status},`${c.name} ${verb}`);showDialog(`${esc(c.name)} ${verb}`,`<p>${status==='suspended'?'정지하면 이 회사의 모든 구성원이 로그인할 수 없습니다. 저장된 증적은 삭제되지 않습니다.':'거절하면 이 회사는 로그인할 수 없으며, 같은 도메인으로 다시 가입하려면 운영자 확인이 필요합니다.'}</p><label class="field">사유 (회사 관리자에게 전달)<textarea id="opsReason" rows="3" placeholder="예: 이용 약관 위반 확인"></textarea></label><div class="actions"><button class="btn danger" id="confirmOps">${verb}</button></div>`);$('#confirmOps').onclick=()=>{const reason=$('#opsReason').value.trim();if(!reason)return toast('사유를 입력하세요.');$('#dialog').close();opsUpdate('company',id,{status,reason},`${c.name} ${verb} (사유: ${reason})`)}}
function bindOps(){document.querySelectorAll('[data-ops-company]').forEach(b=>b.onclick=()=>opsCompanyAction(b.dataset.opsCompany,b.dataset.status));document.querySelectorAll('[data-ops-user]').forEach(b=>b.onclick=()=>{const blocked=b.dataset.blocked==='true';opsUpdate('user',b.dataset.opsUser,{blocked},`${b.dataset.opsUser} 로그인 ${blocked?'차단':'차단 해제'}`)});document.querySelectorAll('[data-ops-members]').forEach(b=>b.onclick=()=>{go('ops-users');state.query=b.dataset.opsMembers;render()});document.querySelectorAll('[data-ops-resend]').forEach(b=>b.onclick=()=>{opsAudit(`${b.dataset.opsResend} 인증 메일 재발송`);toast(b.dataset.opsResend+'로 인증 메일을 다시 보냈습니다.');render()});if($('#saveOpsSettings'))$('#saveOpsSettings').onclick=()=>{const requireApproval=$('#requireApproval').checked,blockedDomains=[...new Set($('#blockedDomains').value.split(/\s+/).map(d=>d.trim().toLowerCase().replace(/^@/,'')).filter(Boolean))];opsUpdate('settings',null,{requireApproval,blockedDomains},`가입 정책 변경 (운영자 승인 ${requireApproval?'필요':'불필요'}, 차단 도메인 ${blockedDomains.length}개)`)}}
function handleAuthLink(){if(!window.location?.search)return false;const q=new URLSearchParams(window.location.search),v=q.get('verify'),i=q.get('invite');if(!v&&!i)return false;history.replaceState(null,'',window.location.pathname);if(v)verifyEmail(v);else openInvite(i);return true}


function home(){const original=nativeHome();const start=original.indexOf('<section class="project-section" id="project-process">');const end=original.indexOf('<footer class="project-footer">');const guide=original.slice(start,end);return `<div class="project-home finvera-home">${siteHeader()}
<section class="landing-hero"><div class="landing-hero-content"><div class="micro"><i class="dot"></i> YOUR EVIDENCE. ALL CONNECTED.</div><h1>증적은 여기.<br>다음은 <em>명확하게.</em></h1><div class="hero-bottom"><button class="pill" data-start-upload>증적 검토 시작하기 ↗</button><div class="line"></div><p>흩어진 문서를 인증기준과 연결하고,<br>판단 근거와 보완 사항까지 확인하세요.</p></div></div><div class="glass-art interactive-folder"><div class="folder-stage" tabindex="0" role="img" aria-label="반투명 폴더. 마우스를 올리거나 초점을 맞추면 파일이 펼쳐집니다."><svg class="folder-back" viewBox="0 0 500 420" aria-hidden="true"><defs><linearGradient id="folder-back-fill" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#e5f2ff" stop-opacity=".8"/><stop offset=".3" stop-color="#a7caff" stop-opacity=".6"/><stop offset=".68" stop-color="#467bdb" stop-opacity=".72"/><stop offset="1" stop-color="#b99bdf" stop-opacity=".65"/></linearGradient><linearGradient id="folder-back-rim" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#f4fbff"/><stop offset=".35" stop-color="#486bb6"/><stop offset=".7" stop-color="#d0ecff"/><stop offset="1" stop-color="#9095ef"/></linearGradient></defs><path d="M100 71Q100 38 134 42L220 51Q237 54 246 78L261 103L410 134Q449 142 443 177L409 337Q403 371 370 365L91 308Q62 302 68 273Z" fill="url(#folder-back-fill)" stroke="url(#folder-back-rim)" stroke-width="5"/><path d="M100 71Q100 38 134 42L220 51Q237 54 246 78L261 103L410 134Q449 142 443 177L409 337Q403 371 370 365L91 308Q62 302 68 273Z" fill="none" stroke="#ecf8ff" stroke-opacity=".42" stroke-width="1" transform="translate(3 -4)"/></svg><div class="folder-paper paper-three"><i></i><i></i><i></i></div><div class="folder-paper paper-two"><i></i><i></i><i></i></div><div class="folder-paper paper-one"><i></i><i></i><i></i></div><svg class="folder-front" viewBox="0 0 500 420" aria-hidden="true"><defs><linearGradient id="folder-front-fill" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#e5f2ff" stop-opacity=".8"/><stop offset=".3" stop-color="#a7caff" stop-opacity=".6"/><stop offset=".68" stop-color="#467bdb" stop-opacity=".72"/><stop offset="1" stop-color="#b99bdf" stop-opacity=".65"/></linearGradient><linearGradient id="folder-front-rim" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#f4fbff"/><stop offset=".35" stop-color="#486bb6"/><stop offset=".7" stop-color="#d0ecff"/><stop offset="1" stop-color="#9095ef"/></linearGradient></defs><path d="M53 124Q47 91 80 98L346 151Q381 158 384 193L402 332Q405 371 369 365L101 312Q76 307 71 281Z" fill="url(#folder-front-fill)" stroke="url(#folder-front-rim)" stroke-width="5"/><path d="M53 124Q47 91 80 98L346 151Q381 158 384 193L402 332Q405 371 369 365L101 312Q76 307 71 281Z" fill="none" stroke="#ecf8ff" stroke-opacity=".42" stroke-width="1" transform="translate(3 -4)"/></svg></div></div><div class="hero-label">IS SO / EVIDENCE REVIEW WORKSPACE</div></section>
<section class="lp-section intro" id="about"><p class="lp-eyebrow">MADE FOR YOUR NEXT REVIEW</p><h2>문서를 모으는 데서 끝나지 않도록.<br><span>증적과 기준 사이,</span><br>검토의 다음 단계를 연결해요.</h2><a class="text-link" href="#features">is so 살펴보기 ↓</a></section>
<section class="lp-section editorial" id="features"><div><p class="lp-eyebrow">LESS SEARCHING. MORE CLARITY.</p><h2>복잡한 인증 준비를,<br>더 명확한 검토 흐름으로.</h2><p>ISMS-P 증적 검토 보조 도구</p></div><div><p class="lead">어떤 기준과 관련 있는지.<br>어떤 근거가 충분한지.<br>무엇을 더 준비해야 하는지.</p><p>증적있소는 문서의 내용을 관련 인증기준과 연결하고, 체크리스트를 바탕으로 검토 결과와 근거를 정리해요. 담당자는 필요한 확인과 보완에 집중할 수 있어요.</p><div class="feature-list"><details class="feature-accordion"><summary><span class="num">01</span><b>증적을 한곳에.</b><small>UPLOAD & ORGANIZE</small><span class="feature-plus">＋</span></summary><div class="feature-expanded"><div class="feature-mini"><span>01</span><strong>UPLOAD<br>ORGANIZE</strong></div><div><h3>문서와 버전을 관리해요.</h3><p>정책서, 점검표, 이행 기록을 등록하고 파일별 처리 상태와 버전을 확인하세요.</p><button class="text-link" data-go="evidence">화면 살펴보기 ↗</button></div></div></details><details class="feature-accordion"><summary><span class="num">02</span><b>기준과 연결해요.</b><small>CONTROL MAPPING</small><span class="feature-plus">＋</span></summary><div class="feature-expanded"><div class="feature-mini"><span>02</span><strong>CONTROL<br>MAPPING</strong></div><div><h3>관련 통제항목을 확인해요.</h3><p>검색 후보와 매핑 이유를 확인하고 주요 관련 항목과 참고 관련 항목을 구분하세요.</p><button class="text-link" data-go="controls">화면 살펴보기 ↗</button></div></div></details><details class="feature-accordion"><summary><span class="num">03</span><b>근거를 확인해요.</b><small>EVIDENCE REVIEW</small><span class="feature-plus">＋</span></summary><div class="feature-expanded"><div class="feature-mini"><span>03</span><strong>EVIDENCE<br>REVIEW</strong></div><div><h3>판단을 원문과 대조해요.</h3><p>문항별 판단 이유와 원문 인용, 페이지 정보를 함께 보며 근거를 확인하세요.</p><button class="text-link" data-go="controls">화면 살펴보기 ↗</button></div></div></details><details class="feature-accordion"><summary><span class="num">04</span><b>다음 보완까지.</b><small>NEXT ACTION</small><span class="feature-plus">＋</span></summary><div class="feature-expanded"><div class="feature-mini"><span>04</span><strong>NEXT<br>ACTION</strong></div><div><h3>확인할 작업을 이어가요.</h3><p>검토 사유와 추가로 필요한 기록을 확인하고 담당자의 검토 결정을 남기세요.</p><button class="text-link" data-go="review">화면 살펴보기 ↗</button></div></div></details></div><p class="tiny-note">AI 검토 결과를 확인하고 최종 판단하는 주체는 담당자입니다.</p></div></section>
<section class="lp-section"><div class="cards-heading"><div><p class="lp-eyebrow">BUILT AROUND YOUR EVIDENCE</p><h2>문서마다 다른 내용.<br>하나로 이어지는 검토.</h2></div><p>정책부터 실제 수행 기록까지,<br>필요한 증적을 기준에 맞춰 확인하세요.</p></div><div class="use-cards"><article class="use-card"><div class="card-lines"></div><div><p class="tags">01 / POLICIES</p><h3>정책 · 절차서</h3></div><div><p>정책의 적용 범위와 역할, 절차가<br>인증기준에 맞게 명시되어 있는지.</p><button class="pill" style="color:#c4daff;border-color:#6e96cf66" data-go="controls">검토 화면 보기 ↗</button></div></article><article class="use-card"><div class="card-lines"></div><div><p class="tags">02 / OPERATION RECORDS</p><h3>대장 · 수행 기록</h3></div><div><p>문서에 적힌 계획이 실제 이력과<br>기록으로 이어지는지.</p><button class="pill" style="color:#c4daff;border-color:#6e96cf66" data-go="controls">검토 화면 보기 ↗</button></div></article><article class="use-card"><div class="card-lines"></div><div><p class="tags">03 / REVIEW & FOLLOW-UP</p><h3>점검 · 조치 결과</h3></div><div><p>발견된 문제에 대한 조치와<br>추가로 필요한 근거는 무엇인지.</p><button class="pill" style="color:#c4daff;border-color:#6e96cf66" data-go="controls">검토 화면 보기 ↗</button></div></article></div></section>
<section class="blue-section" id="start"><p class="lp-eyebrow">START WITH YOUR DOCUMENT</p><h2>필요한 증적, 여기 있소.</h2><p>검토할 파일을 등록하고, 다음 단계로 이어가세요.<br>${config.mode==='demo'?'데모 모드 · 실제 파일 분석은 서버 연결 후 가능합니다.':'서버 연결 모드 · 설정된 서버의 응답을 사용합니다.'}</p><div class="upload-board"><div class="upload-left"><h3>첫 번째 증적을<br>추가해보세요.</h3><p>여러 형식의 증적을 한곳에서 관리해요.<br>${config.mode==='demo'?'데모에서는 예시 판정으로 검토 흐름을 확인해요.':'등록한 파일을 연결된 입력 서버로 전송합니다.'}</p><div class="mini-drop" data-start-upload tabindex="0" role="button" aria-label="증적 파일 선택"><span style="color:#2c68e8;font-size:25px">↥</span><b>파일을 선택해 시작하세요</b><small>PDF · DOCX · XLSX · PPTX · TXT · CSV · 이미지</small></div><button class="pill blue" data-start-upload>파일 선택하기 ↗</button></div><div class="upload-right"><p class="big-number">3 steps.</p><p>업로드부터 검토 결과까지,<br>흐름은 간단하게.</p><div class="process-row"><b>01</b><span>문서 등록<small>증적 파일과 버전 관리</small></span></div><div class="process-row"><b>02</b><span>인증기준 연결<small>관련 통제항목 후보 및 매핑 확인</small></span></div><div class="process-row"><b>03</b><span>검토 결과 확인<small>판단 근거 · 보완 사항 · 사람 검토</small></span></div></div></div></section>
<section class="lp-section workflow-section" id="workflow"><div><p class="lp-eyebrow">FROM FILES TO A CLEAR VIEW</p><h2><span class="heading-line">진행 상황과</span><span class="heading-line">검토 결과,</span><span class="heading-line">한눈에 확인해요.</span></h2><p>보관된 증적, 연결된 기준, 확인이 필요한 결과를<br>하나의 워크스페이스에서 살펴보세요.</p><button class="text-link" data-go="dashboard">워크스페이스 둘러보기 ↗</button></div><div class="preview-board"><div class="preview-top"><strong>증적 검토 워크스페이스</strong><span style="color:#8ca0bf;font-size:11px">${config.mode==='demo'?'DEMO PREVIEW':'WORKSPACE'}</span></div><div class="preview-metrics"><div>전체 증적<b>${state.data.length}</b></div><div>기준 매핑 완료<b>${state.data.filter(d=>d.control_id).length}</b></div><div>검토 필요<b>${state.data.filter(d=>d.review).length}</b></div></div>${state.data.slice(0,3).map(d=>`<div class="preview-row"><span>${esc(d.name)}</span>${badge(d.status)}</div>`).join('')||'<p class="muted">조회된 증적이 없습니다.</p>'}<p style="font-size:11px;color:#99a7ba;margin:20px 0 0">${config.mode==='demo'?'표시된 결과와 수치는 데모 예시입니다.':'아래 수치는 현재 조회된 증적 기준입니다.'}</p></div></section>
<div class="native-guide"><details><summary>점검 과정 · 결과 읽는 법 · 서버 연결 범위 알아보기 <span>＋</span></summary><div class="guide-body">${guide}</div></details></div><section class="final-cta"><div><p class="lp-eyebrow" style="color:#90b6ff">TAKE THE NEXT STEP</p><h2>인증 준비의 다음 단계,<br>증적있소와 함께.</h2><p>관련 기준부터 보완 사항까지, 검토에 필요한 정보를 확인하세요.</p></div><button class="pill" data-go="dashboard">워크스페이스 열기 ↗</button></section><footer class="lp-footer"><div class="footer-columns"><h3>흩어진 증적을 연결하고.<br>검토의 방향을 명확하게.</h3><div><p class="lp-eyebrow">EXPLORE</p><p><a href="#about">서비스 소개</a><br><a href="#features">주요 기능</a><br><a href="#start">증적 검토 시작</a></p></div><div><p class="lp-eyebrow">WORKSPACE</p><p><a href="#workflow">검토 현황</a><br><button class="linkbtn" data-go="dashboard">샘플 대시보드 ↗</button><br>ISMS-P 증적 검토 보조 도구</p></div></div><div class="giant-word">is so.</div><div class="footer-fine"><span>© 2026 증적있소 · is so</span><span>${config.mode==='demo'?'데모 모드 · 실제 AI 분석 미실행':'서버 연결 모드 · 연동 범위 확인 필요'}</span></div></footer></div>`;}

function nativeHome(){return `<div class="project-home"><div class="landing-screen">${siteHeader()}<section class="landing-hero" aria-labelledby="landing-title"><div class="landing-center"><h1 id="landing-title">ISMS-P 인증 준비를 위한<br><span>증적 사전 점검 도구</span></h1><div class="landing-actions"><button class="btn primary hero-upload" data-start-upload>증적 업로드</button><button class="landing-dashboard" data-go="dashboard">대시보드 보기</button></div></div><a class="landing-scroll" href="#project-overview">스크롤하여 도구 설명 보기<span aria-hidden="true">⌄</span></a></section></div><nav class="reading-nav" aria-label="소개 페이지 목차"><div><a href="#project-overview" aria-current="location">프로젝트 개요</a><a href="#project-process">점검 과정</a><a href="#project-results">결과 읽는 법</a><a href="#project-usage">이용 안내</a></div><span class="reading-progress" aria-hidden="true"></span></nav><main class="project-main"><div class="project-kicker"><span>프로젝트 안내</span><span>${config.mode==='demo'?'시연 환경 · 예시 데이터':'서버 연결 환경'}</span></div><section class="project-overview" id="project-overview"><div class="project-lead"><h2>증적과 통제항목을 연결하고,<br>판단의 근거를 확인합니다.</h2><p class="project-summary">제출한 증적이 어느 통제항목에 해당하는지 찾고,<br class="desktop-break"> 요구사항을 확인할 근거가 충분한지 검토합니다.</p><p>인증을 준비할 때는 정책서, 운영 절차, 점검표와 이행 기록을 통제항목에 맞춰 정리해야 합니다. 파일이 제출되었더라도 적용 대상과 기간이 다르거나, 실제 이행을 확인할 기록이 부족할 수 있습니다.</p><p>이 프로젝트는 문서의 내용을 추출해 관련 통제항목에 연결하고, 세부 문항별 판단 이유와 원문 인용을 제시합니다. 담당자는 제시된 근거를 대조하며 추가 자료가 필요한 부분과 검토할 판단을 확인합니다.</p><div class="project-cta"><button class="btn green" data-start-upload>증적 업로드</button><a href="#project-process">점검 과정 살펴보기</a></div></div><aside class="project-scope"><h2>프로젝트 기준</h2><dl><div><dt>점검 범위</dt><dd>관리체계 수립 및 운영<br>보호대책 요구사항<br>개인정보 처리 단계별 요구사항</dd></div><div><dt>기준 데이터</dt><dd><strong>101개 통제항목 · 883문항</strong><small>전체 체크리스트 초안 기준</small></dd></div><div><dt>확인하는 내용</dt><dd>절차 수립 / 실제 이행 / 기록</dd></div><div><dt>판단의 근거</dt><dd>제출 증적의 원문과 위치 정보</dd></div></dl><p>보유 2023년 안내서를 바탕으로 정리한 팀 검수용 초안입니다. 전체 문항의 성능 평가와 최종 승인은 진행 과제이며, 사용 중인 체크리스트 버전에 따라 실행 범위가 달라집니다.</p></aside></section><section class="project-shortcuts" aria-label="작업 선택">${[['dashboard','대시보드','처리 현황과 확인할 작업'],['evidence','증적 관리','파일 등록·검색·버전 확인'],['review','검토 대기','검토 사유 확인과 결정'],['controls','통제항목별 결과','문항 판정과 원문 인용']].map(([v,t,d])=>`<button data-go="${v}"><strong>${t}</strong><span>${d}</span></button>`).join('')}</section><section class="project-section" id="project-process"><div class="section-label">점검 과정</div><div class="section-content"><h2>파일을 등록한 뒤, 관련성과 충족 여부를 차례로 확인합니다.</h2><p class="section-intro">파일의 처리 상태와 기준에 대한 판단은 구분합니다. 전처리가 끝났거나 통제항목이 연결되었다고 해서 요구사항을 충족한 것은 아닙니다.</p><div class="process-entry"><span class="process-tag">입력 · 전처리</span><div><h3>문서에서 텍스트와 위치 정보를 추출합니다.</h3><p>파일 형식과 크기를 검사하고 증적 ID, 해시, 업로드 시간과 버전을 관리합니다. 문서를 검색 가능한 단위로 나누고 페이지·시트·슬라이드 등 확인 가능한 위치를 함께 보존합니다.</p><p class="process-note">지원 형식: PDF, DOCX, XLSX, PPTX, PNG, JPG, TXT, CSV · 파일당 최대 20MB</p></div></div><div class="phase-columns"><article><span class="phase-label">PHASE 1</span><h3>관련 통제항목 매핑</h3><p>증적 내용으로 통제항목 후보를 검색한 뒤, 관련성과 매핑 이유를 판단합니다. 주요 관련 항목과 참고 관련 항목을 구분하고 원문 인용을 연결합니다.</p><dl><dt>확인할 결과</dt><dd>통제항목 번호·이름, 관련성, 매핑 이유, 인용문</dd><dt>판단 예시</dt><dd>사용자 계정 관리 절차서를<br><strong>2.5.1 사용자 계정 관리</strong>에 연결</dd></dl></article><article><span class="phase-label">PHASE 2</span><h3>체크리스트 기반 판정</h3><p>주요 관련 항목의 세부 문항을 대상으로 절차가 있는지, 실제로 이행했는지, 기록을 확인할 수 있는지 검토합니다. 각 문항의 결과와 근거를 바탕으로 종합 결론을 제시합니다.</p><dl><dt>확인할 결과</dt><dd>문항별 충족·미충족·판단 불가, 이유, 인용, 보완 사항</dd><dt>판단 예시</dt><dd>사용자 등록 절차가 있는지와<br>해당 등록 건이 절차대로 처리됐는지를 각각 확인</dd></dl></article></div><div class="process-entry process-review"><span class="process-tag">검증 · 사람 검토</span><div><h3>인용문과 판단이 맞는지 다시 확인합니다.</h3><p>응답 형식과 통제항목 ID, 청크·인용문·페이지의 일치를 검사합니다. 재검토(Self-check)에서는 인용만으로 판단이 성립하는지 확인하고, 근거 상충·OCR 인용·검증 실패 등은 검토 대상으로 연결합니다.</p><p class="process-note">검색 유사도와 LLM 자기평가 신뢰도는 정확도나 인증 충족률을 뜻하지 않습니다.</p></div></div></div></section><section class="project-section" id="project-results"><div class="section-label">결과 읽는 법</div><div class="section-content"><h2>자료 미제출과 실제 미이행을 구분합니다.</h2><p class="section-intro">문항별 판정은 제출된 자료에서 확인할 수 있는 대상·기간·사건에 한정합니다. 일부 사례의 결과를 조직 전체의 충족으로 확대하지 않습니다.</p><div class="result-guide"><div><span class="badge green">충족 · MET</span><p>해당 문항의 요구사항을 충족하는 직접 근거가 있습니다.</p></div><div><span class="badge red">미충족 · NOT_MET</span><p>수행 의무가 있었고, 미수립·미이행·기준 위반을 확인한 근거가 있습니다.</p></div><div><span class="badge amber">판단 불가 · UNKNOWN</span><p>근거가 부족하거나 대상·시점이 불명확합니다. 판독·실행 실패도 포함합니다.</p></div></div><p class="result-footnote">통제항목 종합 결과는 <strong>충족 / 충족(보완 권고) / 확인 필요 / 미충족 / 증적 없음</strong>으로 표시합니다. 종합 결과를 볼 때는 중요 문항 정책과 적용 규칙 버전도 함께 확인합니다.</p><div class="project-case"><div class="case-heading"><h3>예시: 사용자 계정 관리 절차서만 제출한 경우</h3><span>2.5.1 · 설명용 가상 사례</span></div><p>절차서에 “사용자 계정은 승인 후 생성한다”는 내용이 있어도, 특정 계정이 실제로 승인 후 생성되었는지는 신청·승인·처리 기록을 대조해야 합니다.</p><div class="table-wrap"><table class="case-table"><thead><tr><th>확인 문항</th><th>제출된 근거</th><th>확인 방향</th></tr></thead><tbody><tr><td>사용자 등록 절차가 수립되어 있는가?</td><td>검토 범위에 적용되는 사용자 등록 절차서</td><td>절차의 존재를 확인할 수 있음</td></tr><tr><td>검토 대상 사용자 등록 처리가 수립된 절차에 따라 이행되었는가?</td><td>신청·승인·처리 기록 미제출</td><td>판단 불가 · 실제 이행 기록 추가 확인</td></tr></tbody></table></div><p class="case-time"><strong>시점도 함께 확인합니다.</strong> 나중에 개정한 절차나 다른 계정의 처리 기록만으로 과거의 특정 등록 건이 적정하게 처리되었다고 판단하지 않습니다. 당시 적용 절차와 동일 사건의 기록을 연결해야 합니다.</p></div></div></section><section class="project-section project-use" id="project-usage"><div class="section-label">이용 안내</div><div class="section-content"><h2>현재 화면에서 확인할 수 있는 범위</h2><div class="availability"><div><h3>${config.mode==='demo'?'데모 모드':'서버 연결 모드'}</h3><p>${config.mode==='demo'?'예시 증적을 이용해 파일 조회, 매핑·판정 결과 확인, 인용 대조와 검토 흐름을 살펴볼 수 있습니다. 데모에 업로드한 파일은 실제로 분석하지 않으며, 변경 내용은 새로고침 시 초기화됩니다.':'연결된 서버의 증적과 Phase 1 점검 결과를 조회합니다. Phase 2 판정과 검토 저장은 별도 서버 연동이 필요합니다.'}</p></div><div><h3>실제 점검 연결</h3><p>기존 프로젝트의 업로드·전처리·검색·판단 서버를 연결해 Phase 1 점검을 실행합니다. Phase 2 실행·결과 조회와 검토 결정 저장은 추가 연결이 필요한 상태입니다.</p></div></div><p class="project-purpose">이 도구의 결과는 증적 보완과 내부 검토를 위한 사전점검 자료입니다. 최종 인증 적합성 판단을 대신하지 않습니다.</p><div class="project-bottom-actions"><button class="btn green" data-start-upload>증적 업로드</button><button class="btn" data-go="dashboard">대시보드 열기</button></div><details class="source-note"><summary>프로젝트 기준 자료</summary><p>2026-10-05 제공 소스 기준. 전체 체크리스트: phase2-checklist-full-draft-2026-10-03-r1(팀 승인 전). 설명 예시 문항은 2.5.1-Q01·Q02를 사용합니다. 기준 수록 문항 수는 실제 모델 성능이나 현재 서버의 실행 문항 수를 의미하지 않습니다.</p></details></div></section><footer class="project-footer"><span>ISMS-P 증적 사전점검 프로젝트</span><button class="link" data-go="home">프로젝트 안내</button></footer></main></div>`}

function dashboard(){const data=state.data;const outcomes=data.filter(d=>d.outcome&&!d.provisional&&d.status!=='FAILED');return `<div class="metrics">${[['전체 증적',data.length,'등록된 파일'],['처리 중',data.filter(d=>['PREPROCESSING','MAPPING','VALIDATING'].includes(d.status)).length,'현재 실행 중인 작업'],['검토 필요',data.filter(d=>d.review).length,'근거 확인이 필요한 증적'],['처리 실패',data.filter(d=>d.status==='FAILED').length,'실패 단계 확인 필요']].map(([l,n,s])=>`<div class="metric"><label>${l}</label><strong>${n}<span style="font-size:16px;margin-left:6px">건</span></strong><small>${s}</small></div>`).join('')}</div><div class="columns"><div class="card"><div class="card-head"><div><h2>새 증적 점검</h2><p class="muted">증적을 추가하고 관련 통제항목을 확인하세요.</p></div><span class="badge blue">${config.mode==='demo'?'예시 점검 흐름':'Phase 1 실행'}</span></div>${dropzone()}<div class="steps">${['업로드','전처리','매핑','판정','검토'].map((s,i)=>`<div class="step"><b>${i+1}</b>${s}</div>`).join('')}</div></div><div class="card"><div class="card-head"><h2>통제항목 판정 현황</h2><span class="muted">${config.mode==='demo'?'데모 예시':'조회된 결과'}</span></div>${outcomes.length?`<div class="bar">${['충족','충족(보완 권고)','확인 필요','미충족','증적 없음'].map((s,i)=>`<span style="flex:${outcomes.filter(d=>d.outcome===s).length};background:${['#7eaa97','#a6bba6','#9eb6c9','#c7998e','#d3dce1'][i]}"></span>`).join('')}</div>${['충족','충족(보완 권고)','확인 필요','미충족','증적 없음'].map(s=>`<div class="summary-row"><span>${badge(s)}</span><strong>${outcomes.filter(d=>d.outcome===s).length}건</strong></div>`).join('')}<p class="muted" style="margin-top:14px">동일 규칙 예시 결과 · 잠정 결과 ${data.filter(d=>d.provisional).length}건 제외</p>`:'<div class="empty">조회된 판정 결과가 없습니다.</div>'}</div></div><div class="card"><div class="card-head"><h2>최근 증적</h2><button class="link" data-go="evidence">전체 보기</button></div>${table(data.slice(0,5))}</div>`}
function dropzone(){return `<div class="upload" id="drop" role="region" aria-label="증적 파일 선택"><strong>점검할 증적 파일을 선택하세요</strong><p class="upload-instruction">여러 파일을 끌어다 놓아도 됩니다.</p><p class="muted">PDF · DOCX · XLSX · PPTX · PNG · JPG · TXT · CSV<br>파일당 최대 20MB</p><button class="btn primary file-picker" id="choose">파일 선택하기</button><input type="file" id="files" multiple accept=".pdf,.docx,.xlsx,.pptx,.png,.jpg,.txt,.csv" hidden></div>`}
function table(data){return data.length?`<div class="table-wrap"><table><thead><tr><th>증적 파일</th><th>버전</th><th>처리 상태</th><th>매핑</th><th>검토</th><th>업로드</th></tr></thead><tbody>${data.map(d=>`<tr class="clickable" data-id="${esc(d.evidence_id)}" tabindex="0" role="button" aria-label="${esc(d.name)} 상세 보기"><td class="filecell"><strong>${esc(d.name)}</strong><small>${esc(d.evidence_id)} · ${d.size?Math.ceil(d.size/1024)+' KB':'크기 미제공'}</small></td><td>v${d.version}</td><td>${badge(d.status)}</td><td>${d.control_id?`<span class="badge blue">${esc(d.control_id)}</span>`:d.no_match?'매핑 없음':'—'}</td><td>${d.review?badge('PENDING'):'—'}</td><td class="muted">${esc(d.uploaded_at||'—')}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">표시할 증적이 없습니다.</div>'}
function evidence(){let filtered=state.data.filter(d=>(d.name+' '+d.evidence_id).toLowerCase().includes(state.query.toLowerCase())&&(!state.filter||d.status===state.filter));let pages=Math.max(1,Math.ceil(filtered.length/8));state.page=Math.min(state.page,pages);return `<div class="card"><div class="card-head"><div><h2>증적 업로드</h2><p class="muted">파일 선택 후 ‘업로드만 하기’ 또는 ‘업로드 후 점검하기’를 누르세요.</p></div><details><summary>고급 설정</summary><label class="field">검색 후보 수<input id="topk" type="number" value="5" min="1" max="101"></label><label class="field">판단 모델<input id="model" placeholder="서버 기본값 사용"></label></details></div>${dropzone()}${state.files.length?`<div style="margin-top:18px">${state.files.map(f=>`<div class="summary-row"><span>${esc(f.name)} <span class="muted">${Math.ceil(f.size/1024)} KB</span></span>${badge(fileError(f)||'업로드 가능')}</div>`).join('')}</div><div class="actions" style="margin-top:18px"><button class="btn" id="uploadOnly" ${state.busy?'disabled':''}>업로드만 하기</button><button class="btn green" id="uploadInspect" ${state.busy?'disabled':''}>${state.busy?'<span class="spinner"></span>처리 중':'업로드 후 점검하기'}</button><button class="btn" id="clearFiles" ${state.busy?'disabled':''}>선택 해제</button></div>`:''}${state.busy?'<div class="notice">점검 중입니다. 실제 서버 응답을 기다리고 있습니다.</div>':''}</div><div class="card"><div class="card-head"><h2>증적 목록 <span class="muted">${state.data.length}건</span></h2><div class="actions">${config.mode==='live'?'<button class="btn" id="refresh">새로고침</button><button class="btn" id="preprocess">전처리 실행</button>':''}</div></div><div class="toolbar"><input class="search" id="search" placeholder="파일명 또는 증적 ID 검색" value="${esc(state.query)}" aria-label="증적 검색"><select id="filter" aria-label="처리 상태 필터"><option value="">모든 처리 상태</option>${['UPLOADED','PREPROCESSING','PREPROCESSED','MAPPING','VALIDATING','COMPLETED','REVIEW_REQUIRED','FAILED'].map(v=>`<option value="${v}" ${state.filter===v?'selected':''}>${labels[v]}</option>`).join('')}</select></div>${table(filtered.slice((state.page-1)*8,state.page*8))}<div class="foot"><span>${config.mode==='live'?'현재 조회된 범위에서 검색 · 목록 최대 100건':'전체 데모 증적에서 검색'}</span><div class="actions"><button class="btn" id="prev" ${state.page===1?'disabled':''}>이전</button><span>${state.page} / ${pages}</span><button class="btn" id="next" ${state.page===pages?'disabled':''}>다음</button></div></div></div>`}
function controls(){return `<div class="notice">Phase 1은 관련 항목 매핑, Phase 2는 기준 충족 판정입니다. 주요 관련(PRIMARY) 항목을 판정 대상으로 사용합니다.</div><div class="card"><div class="card-head"><h2>항목별 증적 및 판정</h2><span class="muted">${config.mode==='demo'?'예시 통제항목':'조회된 증적 기준'}</span></div><div class="table-wrap"><table><thead><tr><th>통제항목</th><th>증적</th><th>종합 결과</th><th>검토</th><th>결과 보기</th></tr></thead><tbody>${state.data.filter(d=>d.control_id).map(d=>`<tr><td><strong>${esc(d.control_id)}</strong><br><span class="muted">${esc(d.control_name)}</span></td><td>${esc(d.name)}<br><span class="muted">${labels[d.relation]||'주요 관련'}</span></td><td>${d.outcome?badge(d.outcome):'<span class="muted">Phase 2 미연동</span>'}${d.provisional?' <span class="badge amber">잠정 결과</span>':''}</td><td>${d.review?badge('PENDING'):'—'}</td><td><button class="btn" data-result="${d.evidence_id}">결과 확인</button></td></tr>`).join('')}</tbody></table></div>${state.data.some(d=>d.control_id)?'':'<div class="empty">관련 통제항목이 없습니다.</div>'}</div>`}
function review(){const data=state.data.filter(d=>d.review);return `${can('review')?'':'<div class="notice">담당자는 검토 근거를 조회할 수 있으며, 승인·반려 결정은 검토자 또는 관리자가 합니다.</div>'}<div class="card"><div class="card-head"><h2>검토 대기 ${data.length}건</h2><span class="muted">자동 판정의 근거를 확인하세요</span></div>${data.map(d=>`<div class="reviewbox"><div class="actions">${badge('PENDING')}<span class="badge blue">${d.items?.length?'Phase 2':'Phase 1'}</span>${d.provisional?'<span class="badge amber">잠정 결과</span>':''}</div><strong>${esc(d.name)}</strong><p class="muted">${esc(d.control_id||'')} ${esc(d.control_name||'')} · v${d.version}</p><p>${esc((d.review_reasons||[]).map(r=>reasons[r]||r).join(' · '))}</p><button class="btn" data-result="${d.evidence_id}">${can('review')?'근거 확인 및 검토':'근거 확인'}</button></div>`).join('')||'<div class="empty">검토 대기 중인 증적이 없습니다.</div>'}</div>`}
function detail(){let d=state.selected;return `<button class="link" id="back" style="margin-bottom:20px">목록으로 돌아가기</button><div class="heading"><div><h1>${esc(d.name)}</h1><div class="detail-meta"><span>${esc(d.evidence_id)}</span><span>v${d.version}</span><span>${esc(d.uploaded_at)}</span>${badge(d.status)}</div></div><div class="actions"><button class="btn" id="inspect" ${state.busy?'disabled':''}>${state.busy?'점검 중':'점검 실행'}</button><button class="btn" id="replace">재업로드</button>${can('delete')?'<button class="btn danger" id="delete">삭제</button>':''}</div></div>${d.review?`<div class="notice warning"><strong>사람 검토 필요</strong><p>${esc((d.review_reasons||[]).map(r=>reasons[r]||r).join(' · '))}</p></div>`:''}${d.provisional?'<div class="notice warning">잠정 결과 · 미등록 검토 신호로 최종 확정되지 않았습니다.</div>':''}${d.error?`<div class="notice warning">${esc(d.error)}</div>`:''}<div class="tabs">${[['mapping','통제항목 매핑'],['judgment','문항별 판정'],['original','원문·청크'],['history','검토·버전 이력']].map(([t,n])=>`<button data-tab="${t}" class="${state.tab===t?'active':''}">${n}</button>`).join('')}</div>${state.tab==='mapping'?mapping(d):state.tab==='judgment'?judgment(d):state.tab==='original'?original(d):history(d)}<div class="actions"><button class="btn" id="export">결과 JSON 내려받기</button>${d.review?can('review')?'<button class="btn green" id="reviewAction">검토 결정</button>':'<span class="perm-note">검토 결정은 검토자·관리자만 할 수 있습니다.</span>':''}</div>`}
function mapped(d){return d.mapped_controls|| (d.control_id?[{control_id:d.control_id,control_name:d.control_name,relation:d.relation,reason:'증적에서 해당 통제항목의 관리 절차와 수행 내용을 확인했다.',similarity_score:d.similarity,llm_confidence:d.confidence,citations:[{chunk_id:d.evidence_id+'_C001',page:d.source==='ocr'?null:3,quote:d.quote,source:d.source}]}]:[])}
function citations(cs,d){return (cs||[]).map((c,i)=>`<div class="quote"><div class="muted">${esc(d.name)}${c.page!=null?' · 위치 '+esc(c.page):''} · ${esc(c.chunk_id)}${c.source?' · '+esc(c.source):''}</div>${esc(c.quote)}<div style="margin-top:10px"><button class="link" data-quote="${esc(c.chunk_id)}">원문에서 확인</button></div></div>`).join('')}
function mapping(d){const ms=mapped(d);return `<div class="card"><div class="card-head"><h2>Phase 1 · 통제항목 매핑</h2><span class="badge ${ms.length?'green':'blue'}">${ms.length?'MATCHED':d.no_match?'NO_MATCH':'점검 결과 없음'}</span></div><p class="muted">매핑은 관련성 판단이며 기준 충족 여부를 뜻하지 않습니다.</p>${ms.map(c=>`<div class="control"><div class="actions"><span class="badge blue">${esc(c.control_id)}</span>${badge(c.relation)}</div><h3 style="margin-top:12px">${esc(c.control_name)}</h3><p>${esc(c.reason)}</p><div class="scores"><span>검색 유사도 <strong>${c.similarity_score??'—'}</strong></span><span>LLM 자기평가 신뢰도 <strong>${c.llm_confidence??'—'}</strong></span><span>기계적 검증 ${d.validation===true?'통과':d.validation===false?'실패':'미제공'}</span></div>${citations(c.citations,d)}</div>`).join('')||'<div class="empty">관련 통제항목을 찾지 못했거나 점검 결과가 없습니다.</div>'}</div>`}
function judgment(d){return `<div class="card"><div class="card-head"><div><h2>Phase 2 · 문항별 판정</h2><p class="muted">주요 관련 항목의 절차·이행·기록을 확인합니다.</p></div>${d.outcome?badge(d.outcome):''}</div>${d.items?.length?`<div class="notice">${d.outcome==='미충족'?'중요 문항의 미충족이 종합 결론을 결정했습니다.':d.outcome==='확인 필요'?'중요 문항을 확인할 근거가 충분하지 않습니다.':'문항별 결과와 중요 문항 정책을 함께 확인하세요.'}</div><div class="table-wrap"><table class="items"><thead><tr><th>문항 / 유형</th><th>질문 및 판단 이유</th><th>판정</th><th>근거</th></tr></thead><tbody>${d.items.map(i=>`<tr><td>${esc(i.item_id)}<br><span class="muted">${{procedure:'절차',implementation:'실제 이행',record:'기록'}[i.check_kind]||'유형 미제공'}</span><br>${i.critical?'<span class="badge blue">중요 문항</span>':''}</td><td><strong>${esc(i.question||'체크리스트 질문 미연동')}</strong><p class="muted">${esc(i.reason)}</p>${i.reason_codes?.length?`<details><summary>사유 코드</summary>${esc(i.reason_codes.join(', '))}</details>`:''}${i.error_code?`<p class="muted">기술적 판정 실패 · ${esc(i.error_code)}</p>`:''}${i.result!=='MET'?'<p class="muted">추가 확인: 관련 수행 기록과 적용 시점을 확인하세요.</p>':''}</td><td>${badge(i.result)}</td><td>${citations(i.citations,d)||'<span class="muted">제시된 인용 없음</span>'}</td></tr>`).join('')}</tbody></table></div><details style="margin-top:20px"><summary>판정 기준과 버전</summary><p>schema_version: phase2-output-0.3<br>rule_version: overall-v0.1-checkkind<br>critical_policy: check_kind (절차·실제 이행)<br>체크리스트: 데모 예시 · 중요 문항 정책은 임시 기준</p></details>`:`<div class="empty">${d.no_match?'판정할 주요 관련 증적 없음':'Phase 2 HTTP 연결이 필요합니다.'}</div><p class="muted">문항별 판정 모듈은 기존 프로젝트에 있습니다. 실행·결과 조회 API를 연결하면 여기에 표시합니다.</p>`}</div>`}
function chunks(d){const all=mapped(d).flatMap(c=>c.citations||[]).concat((d.items||[]).flatMap(i=>i.citations||[]));return [...new Map(all.map(c=>[c.chunk_id,c])).values()]}
function original(d){return `<div class="card"><div class="card-head"><h2>인용 근거 및 청크</h2><span class="muted">${config.mode==='demo'?'데모 원문 예시':'조회된 인용문'}</span></div>${config.mode==='live'?'<div class="notice">전체 원문·청크 API가 아직 연결되지 않았습니다. 아래는 서버가 반환한 인용문이며 전체 원문이 아닙니다.</div>':''}${chunks(d).map(c=>`<div class="control" id="chunk-${esc(c.chunk_id)}"><span class="badge">${esc(c.chunk_id)}</span><p class="muted">${c.page!=null?'위치 '+c.page+' · ':''}${esc(c.source||'추출 경로 미제공')}</p><p>${state.highlight===c.chunk_id?'<mark>'+esc(c.quote)+'</mark>':esc(c.quote)}</p></div>`).join('')||'<div class="empty">조회할 근거가 없습니다.</div>'}</div>`}
function history(d){return `<div class="card"><div class="card-head"><h2>파일 버전</h2><select id="version" aria-label="파일 버전">${(d.versions||[d.version]).map(v=>`<option value="${v}" ${v===d.version?'selected':''}>v${v}</option>`).join('')}</select></div><p class="muted">파일 교체 이력입니다. 사람의 검토 결정 이력과 구분합니다.</p><div class="summary-row"><span>v${d.version} · ${esc(d.name)}</span><span>${esc(d.uploaded_at)}</span></div>${config.mode==='live'?'<p class="muted">전체 버전 목록 API 미연동 · 버전 번호로 결과 조회 가능</p><div class="actions"><input id="lookupVersion" type="number" min="1" value="1" aria-label="조회할 버전"><button class="btn" id="versionLoad">버전 결과 조회</button></div>':''}</div><div class="card"><h2>검토 결정 이력</h2>${(d.history||[]).map(h=>`<div class="control">${badge(h.status)} <strong>${esc(h.reviewer)}</strong><p>${esc(h.note)}</p>${h.change?`<p class="muted">${esc(h.change)}</p>`:''}<span class="muted">${esc(h.time)} · ${esc(h.phase)}</span></div>`).join('')||'<div class="empty">기록된 검토 결정이 없습니다.</div>'}${config.mode==='demo'?'<p class="muted">데모 기록은 현재 브라우저 세션에서만 유지됩니다.</p>':'<p class="muted">검토 저장·이력 API 추가 연결 필요</p>'}</div>`}
function fileError(f){return !/\.(pdf|docx|xlsx|pptx|png|jpg|txt|csv)$/i.test(f.name)?'지원하지 않는 형식':f.size>20*1024*1024?'20MB 초과':f.size===0?'빈 파일':''}
function chooseFiles(files){state.files=Array.from(files);if(state.files.length>1000){toast('한 번에 최대 1000개까지 선택할 수 있습니다.');state.files=[]}state.view='evidence';state.selected=null;render()}
async function api(base,path,options={}){if(!base)throw Error('연결 설정에서 서버 주소를 입력하세요.');if(state.user?.token)options={...options,headers:{...options.headers,Authorization:'Bearer '+state.user.token}};const res=await fetch(base.replace(/\/$/,'')+path,options);let data;try{data=await res.json()}catch{throw Error('서버 응답이 JSON 형식이 아닙니다.')}if(!res.ok){let d=data.detail||data;throw Error(typeof d==='string'?d:JSON.stringify(d))}return data}
function normalize(raw){return {...raw,name:raw.filename||raw.file_name||raw.original_filename||raw.source_file||raw.name||raw.evidence_id,size:raw.file_size||raw.size,version:raw.version||1,uploaded_at:raw.uploaded_at||raw.upload_time||'',status:raw.status||'UPLOADED',items:[],history:[],versions:[raw.version||1]}}
function absorb(d,r){let s=r.screen||{};const result=r.judgment||r;d.mapped_controls=s.mapped_controls||result.mapped_controls||r.result?.mapped_controls||[];let c=d.mapped_controls[0];d.control_id=c?.control_id;d.control_name=c?.control_name;d.relation=c?.relation;d.no_match=!d.mapped_controls.length;d.review=s.summary?.review_required||s.human_review?.required||result.human_review?.required||false;d.review_reasons=(s.human_review?.reasons||result.human_review?.reasons||[]).map(x=>typeof x==='string'?x:x.code);d.validation=s.summary?.validation_passed??result.validation?.passed;d.status=d.review?'REVIEW_REQUIRED':(s.summary?.processing_status||result.processing_status)==='FAILED'?'FAILED':'COMPLETED';d.rawResult=r;d.phase1Only=true;}
// Demo IDs advance within this session; live IDs remain server-issued.
let evidenceSequence=Math.max(0,...demo.map(d=>Number(d.evidence_id.slice(1))||0));
function nextEvidenceId(){const highest=state.data.reduce((max,d)=>/^E\d+$/.test(d.evidence_id)?Math.max(max,Number(d.evidence_id.slice(1))):max,0);evidenceSequence=Math.max(evidenceSequence,highest)+1;return 'E'+String(evidenceSequence).padStart(4,'0')}
async function upload(inspect,replaceId){const fs=[...state.files];const topk=Number($('#topk')?.value||5),model=$('#model')?.value.trim();if(topk<1||topk>101||!Number.isInteger(topk)){toast('검색 후보 수는 1~101의 정수여야 합니다.');return}state.busy=true;render();let successes=0,errors=[];for(const f of fs){if(fileError(f)){errors.push(f.name+': '+fileError(f));continue}try{if(config.mode==='demo'){let dup=state.data.find(d=>d.name===f.name&&d.size===f.size);if(dup&&!replaceId){toast(f.name+' · 동일 이름·크기의 데모 증적이 있습니다.');continue}let existing=state.data.find(d=>d.evidence_id===replaceId);let d=inspect?sample(replaceId||nextEvidenceId(),f.name,'2.5.1','REVIEW_REQUIRED','확인 필요'):normalize({evidence_id:replaceId||nextEvidenceId(),name:f.name,size:f.size,status:'UPLOADED',uploaded_at:new Date().toLocaleString('ko-KR')});d.uploaded_at=new Date().toLocaleString('ko-KR',{timeZone:'Asia/Seoul'});d.size=f.size;d.file=f;if(existing){d.version=existing.version+1;d.versions=[...(existing.versions||[existing.version]),d.version];state.data[state.data.indexOf(existing)]=d}else state.data.unshift(d);successes++}else{const fd=new FormData();fd.append('file',f);if(replaceId)fd.append('evidence_id',replaceId);if(inspect){fd.append('top_k',topk);if(model)fd.append('model',model)}const r=await api(config.integration,inspect?'/api/upload-and-inspect':'/api/upload',{method:'POST',body:fd});const d=normalize({...r,name:f.name,size:f.size,evidence_id:r.evidence_id||r.result?.evidence_id});if(!d.evidence_id)throw Error('응답에 evidence_id가 없습니다.');if(inspect)absorb(d,r);let prev=state.data.findIndex(x=>x.evidence_id===d.evidence_id);if(prev>=0)state.data[prev]=d;else state.data.unshift(d);if(r.is_duplicate)toast('중복 증적 · '+(r.duplicate_of||d.evidence_id));successes++}}catch(e){errors.push(f.name+': '+e.message)}}state.busy=false;state.files=[];render();toast(`${successes}개 처리 완료${config.mode==='demo'?' · 데모 예시 판정':''}`);if(errors.length)showDialog('파일 처리 결과',`<p>성공 ${successes}개 · 실패 ${errors.length}개</p><pre>${esc(errors.join('\n'))}</pre>`)}
async function refresh(){try{let r=await api(config.input,'/evidence?page=1&size=100');let list=Array.isArray(r)?r:r.items||r.evidence||r.data||r.results;if(!Array.isArray(list))throw Error('목록 응답을 확인하세요.');state.data=list.map(normalize);render();toast('증적 목록을 불러왔습니다.')}catch(e){toast(e.message)}}
async function inspect(){let d=state.selected;state.busy=true;render();try{if(config.mode==='demo'){const {uploaded_at,size,version,versions,history,...judgment}=sample(d.evidence_id,d.name,'2.5.1','REVIEW_REQUIRED','확인 필요');Object.assign(d,judgment);toast('데모 점검 결과를 표시했습니다.')}else{const r=await api(config.integration,'/api/inspect/'+encodeURIComponent(d.evidence_id)+'?top_k=5',{method:'POST'});absorb(d,r);toast('Phase 1 점검 완료 · Phase 2 추가 연결 필요')}}catch(e){d.error=e.message;toast(e.message)}finally{state.busy=false;render()}}
function showDialog(title,body){$('#dialog').innerHTML=`<div class="dialog-head"><h2>${title}</h2><button class="btn" id="closeDialog">닫기</button></div>${body}`;$('#dialog').showModal();$('#closeDialog').onclick=()=>$('#dialog').close()}
function settings(){showDialog('서버 연결 설정',`<label class="field">실행 모드<select id="mode"><option value="demo" ${config.mode==='demo'?'selected':''}>데모 모드</option><option value="live" ${config.mode==='live'?'selected':''}>서버 연결 모드</option></select></label><label class="field">Phase 1 통합 서버 주소<input id="integration" value="${esc(config.integration)}" placeholder="https://your-integration-server.example"></label><label class="field">입력팀 서버 주소<input id="inputServer" value="${esc(config.input)}" placeholder="https://your-input-server.example"></label><div class="notice">배포된 사이트에서 접근 가능한 HTTPS 서버와 CORS 설정이 필요합니다. 로컬 HTTP 서버는 브라우저 정책에 따라 연결이 차단될 수 있습니다.</div><p class="muted">설정은 이 기기에만 저장합니다. 서버 연결 전 증적은 외부로 전송하지 않습니다.</p><div class="actions"><button class="btn" id="checkServer">준비 상태 확인</button><button class="btn primary" id="saveSettings">설정 적용</button></div><pre id="connectionResult" hidden></pre>`);$('#saveSettings').onclick=()=>{let prev=config.mode;config={mode:$('#mode').value,integration:$('#integration').value.trim(),input:$('#inputServer').value.trim()};try{for(let url of [config.integration,config.input])if(url&&!/^https?:$/.test(new URL(url).protocol))throw Error('HTTP 또는 HTTPS 주소를 입력하세요.');localStorage.setItem('isms.settings',JSON.stringify(config))}catch(e){toast('주소 또는 설정 저장을 확인하세요.');return}if(prev!==config.mode)state.data=config.mode==='demo'?structuredClone(demo):[];$('#dialog').close();state.selected=null;render();if(config.mode==='live'&&config.input)refresh()};$('#checkServer').onclick=async()=>{try{let r=await api($('#integration').value.trim(),'/api/readiness');$('#connectionResult').hidden=false;$('#connectionResult').textContent=JSON.stringify(r,null,2)}catch(e){toast(e.message)}}}
function reviewAction(){if(!can('review'))return toast('검토 결정 권한이 없습니다.');let d=state.selected;showDialog('검토 결정',`<p>${esc(d.name)} · v${d.version}</p><label class="field">검토 단계<select id="reviewPhase"><option>Phase 1 매핑</option><option>Phase 2 판정</option></select></label><label class="field">결정<select id="decision"><option value="APPROVED">승인</option><option value="MODIFIED">수정</option><option value="REJECTED">반려</option></select></label><label class="field">검토자 ID<input id="reviewer" placeholder="검토자 ID"></label><label class="field">검토 의견<textarea id="note" placeholder="확인한 근거와 결정 이유"></textarea></label><div id="modifyFields" hidden><label class="field">수정 통제항목<select id="newControl">${catalog.map(c=>`<option value="${c[0]}" ${d.control_id===c[0]?'selected':''}>${c.join(' ')}</option>`).join('')}</select></label><p class="muted">수정 후 매핑·인용을 다시 검증해야 합니다. 기존 결과와 변경 내용을 기록합니다.</p></div><p class="muted">${config.mode==='demo'?'현재 세션에 데모 검토 기록을 남깁니다.':'검토 결정 저장 API 미연동 · 서버에 저장할 수 없습니다.'}</p><button class="btn green" id="saveReview">${config.mode==='demo'?'데모 결정 기록':'저장 연결 안내'}</button>`);$('#decision').onchange=()=>$('#modifyFields').hidden=$('#decision').value!=='MODIFIED';$('#saveReview').onclick=()=>{if(config.mode==='live'){toast('검토 결정 저장·이력 API가 필요합니다.');return}const reviewer=$('#reviewer').value.trim(),note=$('#note').value.trim(),status=$('#decision').value,phase=$('#reviewPhase').value;if(!reviewer||!note){toast('검토자 ID와 의견을 입력하세요.');return}let change='';if(status==='MODIFIED'){let c=catalog.find(c=>c[0]===$('#newControl').value);change=`통제항목 ${d.control_id} → ${c[0]} · 재검증 대기`;d.control_id=c[0];d.control_name=c[1];d.items=[];d.outcome=null;d.mapped_controls=null;d.status='REVIEW_REQUIRED';d.review=true}else if(status==='APPROVED'){d.review=false;d.status=phase==='Phase 1 매핑'?'VALIDATING':'COMPLETED';if(d.provisional){d.provisional=true;d.review=true;d.status='REVIEW_REQUIRED';change='잠정 결과는 자동 확정하지 않음 · 검토 신호 해결 필요'}}else{d.review=true;d.status='REVIEW_REQUIRED'}d.review_status=status;d.history.push({status,reviewer,note,change,phase,time:new Date().toLocaleString('ko-KR')});$('#dialog').close();render();toast('데모 검토 결정을 기록했습니다.')}}
async function deleteEvidence(){if(!can('delete'))return toast('증적 삭제는 관리자만 할 수 있습니다.');let d=state.selected;showDialog('증적 삭제',`<p>${esc(d.name)}을 삭제할까요?</p><p class="muted">${config.mode==='demo'?'현재 데모 목록에서 제거합니다.':'입력팀 서버에 삭제를 요청합니다.'}</p><button class="btn danger" id="confirmDelete">삭제</button>`);$('#confirmDelete').onclick=async()=>{try{if(config.mode==='live')await api(config.input,'/evidence/'+encodeURIComponent(d.evidence_id),{method:'DELETE'});state.data=state.data.filter(x=>x!==d);state.selected=null;$('#dialog').close();render();toast('증적을 삭제했습니다.')}catch(e){toast(e.message)}}}
async function versionLoad(){let d=state.selected,v=Number($('#lookupVersion').value);if(!Number.isInteger(v)||v<1){toast('버전은 1 이상의 정수입니다.');return}try{let r=await api(config.integration,'/api/results/'+encodeURIComponent(d.evidence_id)+'?version='+v);absorb(d,r);d.version=v;render();toast('v'+v+' 결과를 조회했습니다.')}catch(e){toast(e.message)}}
let pollTimer;
async function preprocess(){try{const r=await api(config.input,'/analysis/start',{method:'POST'});showDialog('전처리 진행',`<p id="analysisProgress">${esc(r.message||'전처리 상태 조회 중')}</p><p class="muted">이 진행률은 파싱·청킹 작업에만 해당합니다.</p>`);const update=async()=>{try{let d=await api(config.input,'/analysis/'+encodeURIComponent(r.analysis_id));if(!$('#dialog').open)return;$('#analysisProgress').textContent=`${d.done} / ${d.total} 처리 · 성공 ${d.ok} · 실패 ${d.failed}`;if(d.status==='running')pollTimer=setTimeout(update,1000);else if(d.errors?.length){let p=document.createElement('pre');p.textContent=JSON.stringify(d.errors,null,2);$('#dialog').append(p)}}catch(e){toast(e.message)}};if(r.status==='running')update()}catch(e){toast(e.message)}}
function startEvidenceUpload(){go('evidence');document.getElementById('choose')?.focus({preventScroll:true})}
function bind(){document.querySelectorAll('[data-start-upload]').forEach(b=>b.onclick=startEvidenceUpload);document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));document.querySelectorAll('[data-id]').forEach(b=>{b.onclick=()=>openDetail(b.dataset.id);b.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();openDetail(b.dataset.id)}}});document.querySelectorAll('[data-result]').forEach(b=>b.onclick=()=>{openDetail(b.dataset.result);state.tab='judgment';render()});document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{state.tab=b.dataset.tab;render()});document.querySelectorAll('[data-quote]').forEach(b=>b.onclick=()=>{state.highlight=b.dataset.quote;state.tab='original';render();document.getElementById('chunk-'+state.highlight)?.scrollIntoView({behavior:'smooth',block:'center'})});const on=(id,fn)=>{if($('#'+id))$('#'+id).onclick=fn};on('settings',settings);on('logout',logout);bindTeam();bindOps();on('resendVerify',resendVerify);if($('#inviteForm'))$('#inviteForm').onsubmit=sendInvite;document.querySelectorAll('[data-demo-verify]').forEach(b=>b.onclick=()=>verifyEmail(b.dataset.demoVerify));document.querySelectorAll('[data-demo-invite]').forEach(b=>b.onclick=()=>{state.user=null;state.team=null;openInvite(b.dataset.demoInvite)});document.querySelectorAll('[data-resend-invite]').forEach(b=>b.onclick=()=>inviteAction(b.dataset.resendInvite,'resend'));document.querySelectorAll('[data-cancel-invite]').forEach(b=>b.onclick=()=>inviteAction(b.dataset.cancelInvite,'cancel'));if($('#authForm'))$('#authForm').onsubmit=submitAuth;on('choose',()=>$('#files').click());if($('#files'))$('#files').onchange=e=>chooseFiles(e.target.files);const drop=$('#drop');if(drop){drop.ondragover=e=>{e.preventDefault();drop.classList.add('drag')};drop.ondragleave=()=>drop.classList.remove('drag');drop.ondrop=e=>{e.preventDefault();chooseFiles(e.dataTransfer.files)}}on('uploadOnly',()=>upload(false));on('uploadInspect',()=>upload(true));on('clearFiles',()=>{state.files=[];render()});on('refresh',refresh);on('preprocess',preprocess);if($('#search'))$('#search').oninput=e=>{let pos=e.target.selectionStart;state.query=e.target.value;state.page=1;render();$('#search').focus();$('#search').setSelectionRange(pos,pos)};if($('#filter'))$('#filter').onchange=e=>{state.filter=e.target.value;state.page=1;render()};on('prev',()=>{state.page--;render()});on('next',()=>{state.page++;render()});on('back',()=>{state.selected=null;render()});on('inspect',inspect);on('delete',deleteEvidence);on('reviewAction',reviewAction);on('versionLoad',versionLoad);on('replace',()=>{const d=state.selected;let inp=document.createElement('input');inp.type='file';inp.accept='.pdf,.docx,.xlsx,.pptx,.png,.jpg,.txt,.csv';inp.onchange=()=>{state.files=Array.from(inp.files);if(state.files.length)upload(false,d.evidence_id)};inp.click()});on('export',()=>{let d=state.selected;let safe={...d};delete safe.file;let blob=new Blob([JSON.stringify(safe.rawResult||safe,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=d.evidence_id+'_v'+d.version+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)});if($('#version'))$('#version').onchange=()=>toast('이전 버전 원문은 버전 조회 API 연결이 필요합니다.')}
state.platform={requireApproval:false,blockedDomains:[...freeMail]};seedDemoCompany();seedPlatform();if(!handleAuthLink())render();if(config.mode==='live'&&config.input)refresh();
const ctx=document.modelContext;if(ctx?.registerTool){const lifecycle=new AbortController();for(const tool of [{name:'navigate_evidence_workspace',description:'대시보드, 증적 관리, 통제항목 결과 또는 검토 대기 화면을 엽니다.',inputSchema:{type:'object',properties:{view:{enum:['home','dashboard','evidence','controls','review']}},required:['view'],additionalProperties:false},annotations:{readOnlyHint:false},execute:({view})=>{if(!['home','dashboard','evidence','controls','review'].includes(view))throw Error('잘못된 화면');go(view);return {view}}},{name:'read_evidence_summary',description:'현재 화면에서 조회된 증적 ID와 처리 상태를 읽습니다.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:()=>({mode:config.mode,evidence:state.data.map(d=>({evidence_id:d.evidence_id,name:d.name,status:d.status,review_required:d.review}))})}]){try{Promise.resolve(ctx.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{})}catch{}}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true})}
